--[[- rpv/route.lua ? small route table with longest-prefix match.]]
local M = ...
local masked, int2ip = M.masked, M.int2ip

function M.route_new() return { entries = {} } end

function M.route_add(rt, prefix, net, iface, gw, kind)
    rt.entries[#rt.entries + 1] = { prefix = prefix, net = net, iface = iface, gw = gw, kind = kind or "static" }
    return rt.entries[#rt.entries]
end

function M.route_connected(rt, iface)
    return M.route_add(rt, iface.prefix, iface.net, iface, nil, "connected")
end

function M.route_default(rt, gw)
    return M.route_add(rt, 0, 0, nil, gw, "default")
end

-- explicit preference when two routes have the same prefix length: a directly
-- connected subnet beats a configured route, which beats anything learned by a
-- routing protocol, which beats the default route.
local RANK = { connected = 4, fabric = 4, file = 3, static = 3, api = 3, dhcp = 3, dv = 2, default = 1 }
M.ROUTE_RANK = RANK

function M.route_lookup(rt, dst)
    -- longest prefix wins; on a tie the entry added first wins (connected routes are
    -- installed at boot, so they naturally beat learned ones). Priority between
    -- kinds is enforced when a route is installed (see route_upsert/DV), not here:
    -- keeping this loop behaviour-preserving matters for every existing topology.
    local best
    for _, r in ipairs(rt.entries) do
        if masked(dst, r.prefix) == r.net and (not best or r.prefix > best.prefix) then best = r end
    end
    return best
end

-- replace (or drop) an entry of a given kind: used by the DV module so repeated
-- announcements update a route instead of piling up duplicates
function M.route_upsert(rt, prefix, net, iface, gw, kind, drop)
    local kept = {}
    for _, r in ipairs(rt.entries) do
        local same = (r.kind == kind and r.net == net and r.prefix == prefix and r.iface == iface)
        if not same then kept[#kept + 1] = r end
    end
    rt.entries = kept
    if drop then return nil end
    return M.route_add(rt, prefix, net, iface, gw, kind)
end

-- resolve a route into a path {iface=, next_hop=}
function M.route_path(rt, dst)
    local r = M.route_lookup(rt, dst)
    if not r then return nil end
    if r.gw then
        local r2 = M.route_lookup(rt, r.gw)
        if not r2 or r2.gw then return nil end
        return { iface = r2.iface, next_hop = r.gw, prefix = r.prefix }
    end
    return { iface = r.iface, next_hop = dst, prefix = r.prefix }
end

function M.route_list(rt)
    local out = {}
    for _, r in ipairs(rt.entries) do
        out[#out + 1] = {
            dest = int2ip(r.net) .. "/" .. r.prefix,
            via = r.gw and int2ip(r.gw) or (r.iface and r.iface.name or "-"),
            kind = r.kind,
        }
    end
    return out
end

return M
]==],
    arp = [==[
--[[- rpv/arp.lua ? neighbour discovery with a request queue.

Unlike the first prototype (which blocked inside a nested event loop and dropped
packets while waiting), an unresolved next hop queues the packet and the node
flushes the queue when the reply arrives. Requests are rate limited and retried.
]]
local M = ...
local r16, r32, u16, u32, int2ip = M.r16, M.r32, M.u16, M.u32, M.int2ip

local RETRY_AFTER = 0.5
local MAX_TRIES = 4
local GIVE_UP = 4
local CACHE_TTL = 120

function M.arp_new()
    return { cache = {}, pending = {}, requests = 0, hits = 0, timeouts = 0, replies = 0 }
end

function M.arp_send(node, iface, op, tmac, tip)
    local body = u16(op) .. u32(node.mac) .. u32(iface.ip) .. u32(tmac) .. u32(tip)
    M.link_send(node, iface, op == 1 and M.MAC_BCAST or tmac, M.ET_ARP, body)
end

-- body layout (L2 header already stripped):
--   op(2) | senderMAC(4) | senderIP(4) | targetMAC(4) | targetIP(4)  = 18 bytes
function M.arp_input(node, iface, frame)
    if #frame < 18 then return end
    local op = r16(frame, 1)
    local smac, sip = r32(frame, 3), r32(frame, 7)
    local tip = r32(frame, 15)
    node.arp.cache[sip] = { mac = smac, expires = os.clock() + CACHE_TTL }
    if op == 1 and tip == iface.ip then
        node.arp.replies = node.arp.replies + 1
        M.arp_send(node, iface, 2, smac, sip)
        node:log("ARP_REPLY to %s mac=%d", int2ip(sip), smac)
    end
    local p = node.arp.pending[sip]
    if p then
        node.arp.pending[sip] = nil
        node:log("ARP_RESOLVED who=%s mac=%d queued=%d", int2ip(sip), smac, #p.cbs)
        for _, cb in ipairs(p.cbs) do cb(smac) end
    end
    return true
end

-- cb(mac) on success, cb(nil, reason) on failure
function M.arp_resolve(node, iface, ip, cb)
    local e = node.arp.cache[ip]
    if e and e.expires > os.clock() then
        node.arp.hits = node.arp.hits + 1
        return cb(e.mac)
    end
    local p = node.arp.pending[ip]
    if not p then
        -- last is back-dated so the very first request goes out immediately,
        -- even if the computer only booted a moment ago
        p = { cbs = {}, iface = iface, first = os.clock(), last = os.clock() - RETRY_AFTER, tries = 0 }
        node.arp.pending[ip] = p
        node:log("ARP_QUEUE who=%s via=%s", int2ip(ip), iface.name)
    end
    p.cbs[#p.cbs + 1] = cb
    local now = os.clock()
    if now - p.last >= RETRY_AFTER and p.tries < MAX_TRIES then
        p.last, p.tries = now, p.tries + 1
        node.arp.requests = node.arp.requests + 1
        node:log("ARP_REQUEST who=%s via=%s try=%d", int2ip(ip), iface.name, p.tries)
        M.arp_send(node, p.iface, 1, 0, ip)
    end
end

function M.arp_tick(node)
    local now = os.clock()
    for ip, e in pairs(node.arp.cache) do
        if e.expires < now then node.arp.cache[ip] = nil end
    end
    for ip, p in pairs(node.arp.pending) do
        if now - p.first > GIVE_UP then
            node.arp.pending[ip] = nil
            node.arp.timeouts = node.arp.timeouts + 1
            node:log("ARP_TIMEOUT who=%s dropped=%d", int2ip(ip), #p.cbs)
            for _, cb in ipairs(p.cbs) do cb(nil, "timeout") end
        elseif now - p.last >= RETRY_AFTER and p.tries < MAX_TRIES then
            p.last, p.tries = now, p.tries + 1
            node.arp.requests = node.arp.requests + 1
            node:log("ARP_RETRY who=%s try=%d", int2ip(ip), p.tries)
            M.arp_send(node, p.iface, 1, 0, ip)
        end
    end
end

return M
]==],
    link = [==[
--[[- rpv/link.lua ? link layer: frames over modem channels.

An interface is one modem side + one channel. Frames are
  dstMAC(4) | srcMAC(4) | ethertype(2) | body
MACs are computer IDs. (The rednet WAN link and the cluster fabric plug in here
in M2 ? they only need to override link_send / the event source.)
]]
local M = ...
local u16, u32, r16, r32 = M.u16, M.u32, M.r16, M.r32

function M.link_open(iface)
    peripheral.call(iface.side, "open", iface.channel)
end

function M.link_send(node, iface, dstmac, etype, body)
    -- test hook: simulate a dead link / dead peer (nothing leaves the node).
    -- Like drop_every this exists so failure modes can be exercised deterministically.
    if node.cfg.block_egress == "1" then
        node.stats.blocked_tx = (node.stats.blocked_tx or 0) + 1
        if (node.stats.blocked_tx % 20) == 1 then
            node:log("LINK_BLOCKED dstmac=%d etype=0x%04X (block_egress=1)", dstmac, etype)
        end
        return 0
    end
    -- QoS scheduler hook (qos.lua): when enabled, frames are queued by priority and
    -- drained by a tick task instead of going straight out. The scheduler itself
    -- transmits through link_send with node.qos.bypass set, so this cannot recurse.
    if node.qos and not node.qos.bypass then
        local q = M.qos_enqueue
        if q and q(node, iface, dstmac, etype, body) then return 0 end
    end
    local frame = u32(dstmac) .. u32(node.mac) .. u16(etype) .. body
    peripheral.call(iface.side, "transmit", iface.channel, node.mac, frame)
    node.stats.frames_tx = node.stats.frames_tx + 1
    node.stats.bytes_tx = node.stats.bytes_tx + #frame
    if node.capture_on then node:cap_push("tx", iface, dstmac, etype, frame) end
    return #frame
end

function M.link_parse(frame)
    if type(frame) ~= "string" or #frame < 10 then return nil end
    return r32(frame, 1), r32(frame, 5), r16(frame, 9), M.sub(frame, 11)
end

return M
