        if node.on_icmp_error then node.on_icmp_error(h.src, itype, code, inner, qseq, code == 4 and r16(payload, 7) or nil) end
    else
        node:log("ICMP_TYPE_%d from=%s", itype, int2ip(h.src))
    end
end

return M
