--[[- rpv/udp.lua ? UDP datagrams + the socket API apps use.

A socket is a small object; because the node owns the event loop, apps are
callback driven:

    local sk = node:bind(9000)
    sk:on_receive(function(data, src, sport)
        sk:sendto(src, sport, "echo:" .. data)
    end)

There is deliberately no blocking recvfrom: inside one CC computer the node's
event loop is the only thing allowed to call os.pullEvent, so apps must either
use callbacks or node:after() timers. That is the same model as rednet.receive
vs os.pullEvent in vanilla CC.
]]
local M = ...
local u8, u16, u32, r16, cksum, sub, int2ip = M.u8, M.u16, M.u32, M.r16, M.cksum, M.sub, M.int2ip

function M.udp_new()
    return { ports = {}, tx = 0, rx = 0, dropped = 0, bad_cksum = 0 }
end

function M.udp_send(node, dst, sport, dport, data, ttl, src, df)
    src = src or node:pick_src(dst)
    local len = 8 + #data
    local pseudo = u32(src) .. u32(dst) .. u8(0) .. u8(M.IP_UDP) .. u16(len)
    local ck = cksum(pseudo .. u16(sport) .. u16(dport) .. u16(len) .. u16(0) .. data)
    if ck == 0 then ck = 0xFFFF end
    local hdr = u16(sport) .. u16(dport) .. u16(len) .. u16(ck)
    node.udp.tx = node.udp.tx + 1
    return node:send_ip(dst, M.IP_UDP, hdr .. data, ttl or 64, src, df)
end

function M.udp_bind(node, port, cb)
    local sk = { port = port, node = node, tx = 0, rx = 0, closed = false, handler = cb }
    function sk:on_receive(fn) self.handler = fn end
    function sk:sendto(dst, dport, data, ttl)
        if self.closed then return false end
        self.tx = self.tx + 1
        return M.udp_send(self.node, dst, self.port, dport, data, ttl)
    end
    function sk:reply(data, src, sport) return self:sendto(src, sport, data) end
    function sk:close()
        self.closed = true
        self.node.udp.ports[self.port] = nil
    end
    function sk:stats() return { port = self.port, rx = self.rx, tx = self.tx, closed = self.closed } end
    node.udp.ports[port] = sk
    return sk
end

function M.udp_input(node, iface, h, payload)
    if #payload < 8 then return end
    local sport, dport, len = r16(payload, 1), r16(payload, 3), r16(payload, 5)
    local data = sub(payload, 9)
    local pseudo = u32(h.src) .. u32(h.dst) .. u8(0) .. u8(M.IP_UDP) .. u16(len)
    local ck = r16(payload, 7)
    local expected = cksum(pseudo .. sub(payload, 1, 6) .. u16(0) .. data)
    if ck ~= 0 and ck ~= expected then
        node.udp.bad_cksum = node.udp.bad_cksum + 1
        node:log("UDP_BAD_CKSUM from=%s dport=%d", int2ip(h.src), dport)
        return
    end
    node.udp.rx = node.udp.rx + 1
    local sk = node.udp.ports[dport]
    if not sk or sk.closed then
        node.udp.dropped = node.udp.dropped + 1
        node:log("UDP_NO_PORT dport=%d from=%s sport=%d bytes=%d", dport, int2ip(h.src), sport, #data)
        if node.icmp_port_unreachable then M.icmp_error(node, iface, h, payload, 3, 3) end
        return
    end
    sk.rx = sk.rx + 1
    node:log("UDP_RECV dport=%d from=%s sport=%d bytes=%d", dport, int2ip(h.src), sport, #data)
    if sk.handler then sk.handler(data, h.src, sport, sk) end
end

return M
]==],
    conn = [==[
--[[- rpv/conn.lua ??connection-oriented transport with AIMD congestion control.

Sits on top of the UDP sockets and gives apps a real connection:

  * 3-way handshake (SYN / SYN-ACK / ACK) with retransmission and backoff
  * cumulative ACKs, sequence numbers, in-order delivery
  * sliding window limited by  min(cwnd, rwnd)
  * AIMD congestion control: slow start (cwnd *= 2) until ssthresh, then
    congestion avoidance (cwnd += 1); RTO collapse (cwnd = 1, ssthresh = cwnd/2,
    RTO *= 2) and fast retransmit after 3 duplicate ACKs
  * RTO from RFC 6298-style SRTT/RTTVAR, with a floor of conn_rto_min
    (real Minecraft quantises to 50 ms ticks, so a sane floor matters)
  * FIN / close

Wire format (one UDP datagram per segment):
  u8 type | u32 seq | u32 ack | u16 window | u16 len | payload
  types: 1 SYN, 2 SYN-ACK, 3 DATA (len=0 means pure ACK), 4 FIN

SECURE MODE (control-plane AEAD, opt-in with node config `conn_secure=1`):
  * handshake authentication: SYN carries "C"|nonce_c|HMAC(k_ctrl, "SYN"|iss|nonce_c)
    and SYN-ACK carries "S"|nonce_s|HMAC(k_ctrl, "SYNACK"|iss|nonce_c|nonce_s), with
    k_ctrl = HKDF(psk, "", "rpv-conn-ctrl-v1"). A peer without the PSK cannot
    complete the handshake, and a secure node talking to a plaintext peer fails
    closed (CONN_SEC_PEER_PLAINTEXT + abort).
  * per-direction session keys from both nonces:
      k_c2s/m_c2s = HKDF(psk, nonce_c|nonce_s, "rpv-conn-c2s"[-mac])
      k_s2c/m_s2c = HKDF(psk, nonce_c|nonce_s, "rpv-conn-s2c"[-mac])
  * every segment is encrypt-then-MAC: hdr(13) | ChaCha20(payload, nonce_dir, counter=seq) | tag(16)
    The header stays plaintext (seq/ack/win are needed for demux and are covered
    by the tag), the payload is encrypted, and the tag is HMAC-SHA256 truncated.
    A failure is counted (CONN_SEC_AUTH_FAIL) and the segment is dropped silently.
  * replay/ordering: the existing rcv_nxt check drops old segments (counted as
    out-of-order); the tag means an attacker cannot forge a fresh sequence number.
  * PSK config: conn_psk=<hex|passphrase>, conn_psk_iter (PBKDF2 rounds for a
    passphrase), conn_sec_mac_len (tag length, default 16).
  Cost note (measured): pure-Lua ChaCha20 is ~215 KB/s, so this is for control
  flows / modest transfers ? bulk data should use link isolation instead.

Test hook: node.cfg.drop_every=N silently drops every Nth outgoing segment so
loss recovery / congestion control can be exercised deterministically.
]]
local M = ...
local u8, u16, u32, r16, r32, byte, sub, int2ip, floor = M.u8, M.u16, M.u32, M.r16, M.r32, M.byte, M.sub, M.int2ip, M.floor

local T_SYN, T_SYNACK, T_DATA, T_FIN, T_SACK = 1, 2, 3, 4, 5
local HDR = 13
M.CONN_TYPES = { SYN = T_SYN, SYNACK = T_SYNACK, DATA = T_DATA, FIN = T_FIN, SACK = T_SACK }

-- SACK option payload: u8 count | (u32 left | u32 right) * count
local function sack_encode(ranges)
    local out = { u8(#ranges) }
    for _, r in ipairs(ranges) do
        out[#out + 1] = u32(r[1]) .. u32(r[2])
    end
    return table.concat(out)
end

local function sack_decode(s)
    if type(s) ~= "string" or #s < 1 then return {} end
    local n, out = byte(s, 1), {}
    for i = 0, n - 1 do
        local o = 2 + i * 8
        if #s < o + 7 then break end
        out[#out + 1] = { r32(s, o), r32(s, o + 4) }
    end
    return out
end

-- advertised receive window, optionally scaled (conn_wscale must match on both ends)
local function adv_win(c)
    local w = c.rwnd or 8192
    if (c.wscale or 0) > 0 then w = floor(w / 2 ^ c.wscale) end
    return w
end

local function seg(t, seq, ack, win, payload)
    return u8(t) .. u32(seq) .. u32(ack) .. u16(win) .. u16(#payload) .. payload
end

function M.conn_parse(data)
    if #data < HDR then return nil end
    local len = r16(data, 12)
    if #data < HDR + len then return nil end
    return {
        t = byte(data, 1), seq = r32(data, 2), ack = r32(data, 6),
        win = r16(data, 10), len = len, payload = sub(data, HDR + 1, HDR + len),
        raw = data,          -- the tag lives after the payload for secure segments
    }
end

-- ===== secure mode helpers ==================================================
local SEC_INFO_CTRL = "rpv-conn-ctrl-v1"
local SEC_INFO_NONCE = "-nonce"

local function sec_is_hex(s)
    return #s >= 32 and #s % 2 == 0 and not s:find("[^0-9a-fA-F]")
end

-- PSK -> 32-byte key. Hex of >=32 bytes is used as raw key material; anything
-- else is a passphrase stretched with PBKDF2 (yielding so CC's watchdog is happy).
function M.conn_psk_derive(node)
    local spec = node.cfg.conn_psk
    if not spec or spec == "" then return nil end
    local raw
    if sec_is_hex(spec) then
        raw = M.unhex(spec)
    else
        local iters = tonumber(node.cfg.conn_psk_iter) or 256
        raw = (iters > 0) and M.pbkdf2_sha256(spec, "rpv-conn", iters, 32, 32) or spec
    end
    return M.hkdf_sha256(raw, "", "rpv-conn-psk-v1", 32)
end

function M.conn_rand(n)
    local out = {}
    for i = 1, n do
        out[i] = string.char(math.random(0, 255))
    end
    return table.concat(out)
end

local function sec_tag(c, key, ...)
    return M.hmac_sha256(key, table.concat({ ... })):sub(1, c.sec_mac)
end

local function sec_derive(c)
    local salt = c.nonce_c .. c.nonce_s
    local a, b = M.hkdf_sha256(c.psk, salt, "rpv-conn-c2s", 32), M.hkdf_sha256(c.psk, salt, "rpv-conn-c2s-mac", 32)
    local x, y = M.hkdf_sha256(c.psk, salt, "rpv-conn-s2c", 32), M.hkdf_sha256(c.psk, salt, "rpv-conn-s2c-mac", 32)
    if c.is_client then
        c.k_tx, c.m_tx, c.k_rx, c.m_rx = a, b, x, y
    else
        c.k_tx, c.m_tx, c.k_rx, c.m_rx = x, y, a, b
    end
    c.nonce_tx = M.hkdf_sha256(c.psk, salt, "rpv-conn-c2s" .. SEC_INFO_NONCE, 12)
    c.nonce_rx = M.hkdf_sha256(c.psk, salt, "rpv-conn-s2c" .. SEC_INFO_NONCE, 12)
    if not c.is_client then
        c.nonce_tx, c.nonce_rx = c.nonce_rx, c.nonce_tx
    end
    c.sec_ready = true
    c.node:log("CONN_SEC_KEYS role=%s fp=%s", c.is_client and "client" or "server",
        M.hex(M.sha256(c.k_tx)):sub(1, 8))
end

-- header (13 B) | ciphertext | tag   (control segments: payload plaintext + tag)
local function sec_wrap(c, t, seq, ack, win, payload, encrypt)
    local body = encrypt and M.chacha20_xor(c.k_tx, c.nonce_tx, seq, payload) or payload
    local hdr = u8(t) .. u32(seq) .. u32(ack) .. u16(win) .. u16(#body)
    return hdr .. body .. sec_tag(c, c.m_tx, hdr, body)
end

local Conn = {}
Conn.__index = Conn

local function count(t)
    local n = 0
    for _ in pairs(t) do n = n + 1 end
    return n
end

function M.conn_new(node, opts)
    local c = setmetatable({
        node = node, port = opts.port, peer_ip = opts.peer_ip, peer_port = opts.peer_port or opts.port,
        state = opts.state or "CLOSED", mss = tonumber(node.cfg.conn_mss) or 200,
        snd_una = 0, snd_nxt = 0, rcv_nxt = 0,
        cwnd = 1, ssthresh = tonumber(node.cfg.conn_ssthresh) or 16,
        rwnd = tonumber(node.cfg.conn_rwnd) or 8192,
        srtt = nil, rttvar = nil,
        rto = tonumber(node.cfg.conn_rto) or 0.5,
        -- 0.2 s = 4 server ticks. Measured on a real Minecraft/CC:Tweaked server:
        -- with the old 0.05 s floor a 200 kB burst fired 12 spurious RTOs
        -- (cwnd collapsing to 1 each time) while 0.2 s produced none at the same
        -- throughput (1.5 s, ~133 kB/s). See poc/out/measurements-mc.md 2.12(d).
        rto_min = tonumber(node.cfg.conn_rto_min) or 0.2,
        rto_max = tonumber(node.cfg.conn_rto_max) or 2.0,
        tx = 0, retx = 0, bytes_tx = 0, bytes_rx = 0, dupacks = 0, dup_rx = 0,
        queue = {}, unacked = {}, closed = false, fin_sent = false, close_pending = false,
        -- secure mode (control-plane AEAD): see the header comment
        secure = false, sec_mac = tonumber(node.cfg.conn_sec_mac_len) or 16,
        sec_drops = { auth = 0, ctrl = 0, plaintext_peer = 0 },
        -- P3 transport polish: selective ACKs, window scaling, slow start, keepalive
        sack = (node.cfg.conn_sack ~= "0"),
        wscale = tonumber(node.cfg.conn_wscale) or 0,
        iw = tonumber(node.cfg.conn_iw) or 2,
        keepalive = tonumber(node.cfg.conn_keepalive) or 0,
        gmax = tonumber(node.cfg.conn_global_max_inflight) or 0,
        ooo = {}, ooo_bytes = 0, sack_rx = 0, sack_retx = 0, sack_sent = 0, ooo_buffered = 0,
        keepalives = 0, ka_miss = 0, last_activity = os.clock(),
    }, Conn)
    local id = node.id or os.getComputerID()
    c.iss = (id * 100000 + floor((os.clock() * 1000)) % 100000) % 2 ^ 31
    c.snd_una, c.snd_nxt = c.iss, c.iss
    c.cwnd = c.iw                      -- initial window (RFC 6928-style)
    c.is_client = (c.state == "SYN_SENT")
    if node.cfg.conn_secure == "1" then
        c.psk = M.conn_psk_derive(node)
        if not c.psk then
            node:log("CONN_SEC_NO_PSK (conn_secure=1 but conn_psk is empty)")
        else
            c.secure = true
            c.k_ctrl = M.hkdf_sha256(c.psk, "", SEC_INFO_CTRL, 32)
            c.nonce_c = M.conn_rand(8)
            if not c.is_client then c.nonce_s = M.conn_rand(8) end
        end
    end
    return c
end

function Conn:on_open(fn) self.open_cb = fn end
function Conn:on_data(fn) self.data_cb = fn end
function Conn:on_close(fn) self.close_cb = fn end

function Conn:_send_ctrl(t, seq, ack, payload)
    payload = payload or ""
    local frame
    if self.secure and self.sec_ready and t ~= T_SYN and t ~= T_SYNACK then
        -- control segments (pure ACK / FIN / handshake ACK) are authenticated too
        frame = sec_wrap(self, t, seq, ack, adv_win(self), payload, false)
    else
        frame = seg(t, seq, ack, adv_win(self), payload)
    end
    M.udp_send(self.node, self.peer_ip, self.port, self.peer_port, frame, 64)
    self.tx = self.tx + 1
end

function Conn:_transmit(rec)
    rec.sent = true
    rec.t0 = os.clock()
    rec.tries = (rec.tries or 0) + 1
    self.tx = self.tx + 1
    self.bytes_tx = self.bytes_tx + #rec.data
    local drop_every = tonumber(self.node.cfg.drop_every) or 0
    if drop_every > 0 and rec.tries == 1 and self.tx % drop_every == 0 then
        self.node:log("CONN_DROP_SIM seq=%d bytes=%d (drop_every=%d)", rec.seq, #rec.data, drop_every)
    else
        local frame
        if self.secure and self.sec_ready then
            frame = sec_wrap(self, T_DATA, rec.seq, self.rcv_nxt, adv_win(self), rec.data, true)
        else
            frame = seg(T_DATA, rec.seq, self.rcv_nxt, adv_win(self), rec.data)
        end
        M.udp_send(self.node, self.peer_ip, self.port, self.peer_port, frame, 64)
    end
    -- count segments, not transmits: retransmitting an existing record must not
    -- inflate the node-wide in-flight total used by the fairness cap
    if not self.unacked[rec.seq] then
        self.node.conn_inflight = (self.node.conn_inflight or 0) + 1
    end
    self.unacked[rec.seq] = rec
end

function Conn:send(data)
    if self.state ~= "ESTABLISHED" then return false end
    local i = 1
    while i <= #data do
        local chunk = sub(data, i, i + self.mss - 1)
        i = i + self.mss
        self.queue[#self.queue + 1] = { seq = self.snd_nxt, data = chunk, sent = false }
        self.snd_nxt = self.snd_nxt + #chunk
    end
    self:pump()
    return true
end

function Conn:pump()
    if self.state ~= "ESTABLISHED" then return end
    local win = math.min(self.cwnd, math.max(1, floor(self.rwnd / self.mss)))
    -- the peer tells us how much room it has (its window may be scaled)
    if self.peer_rwnd and self.peer_rwnd > 0 then
        win = math.min(win, math.max(1, floor(self.peer_rwnd / self.mss)))
    end
    local inflight = count(self.unacked)
    for _, rec in ipairs(self.queue) do
        if inflight >= win then break end
        -- fairness: a node-wide in-flight cap keeps N flows from oversubscribing.
        -- A flow with nothing in flight may always send one segment, otherwise a new
        -- flow could never get started while other flows hold the whole budget.
        if self.gmax > 0 and (self.node.conn_inflight or 0) >= self.gmax and inflight > 0 then
            self.cwnd_limited = (self.cwnd_limited or 0) + 1
            break
        end
        if not rec.sent then
            self:_transmit(rec)
            inflight = inflight + 1
        end
    end
    if self.close_pending and inflight == 0 then self:_finish_close() end
end

function Conn:_rtt(r)
    if not self.srtt then
        self.srtt, self.rttvar = r, r / 2
    else
        self.rttvar = 0.75 * self.rttvar + 0.25 * math.abs(self.srtt - r)
        self.srtt = 0.875 * self.srtt + 0.125 * r
    end
    self.rto = math.max(self.rto_min, math.min(self.rto_max or 2.0, self.srtt + 4 * self.rttvar))
end

function Conn:_on_ack(ack)
    local acked = 0
    for seq, rec in pairs(self.unacked) do
        if seq + #rec.data <= ack then
            self.unacked[seq] = nil
            self.node.conn_inflight = math.max(0, (self.node.conn_inflight or 0) - 1)
            acked = acked + 1
            if rec.tries == 1 and rec.t0 then self:_rtt(os.clock() - rec.t0) end
            for i = #self.queue, 1, -1 do
                if self.queue[i] == rec then table.remove(self.queue, i) end
            end
        end
    end
    if acked > 0 then
        self.snd_una = ack
        self.dupacks = 0
        -- AIMD
        if self.cwnd < self.ssthresh then
            -- proper slow start: +1 MSS per ACK (doubles per RTT). The legacy curve
            -- doubled per ACK, which overshoots badly on a 50 ms-tick link.
            if self.node.cfg.conn_slow_start == "1" then self.cwnd = self.cwnd + self.mss
            else self.cwnd = self.cwnd * 2 end
        else self.cwnd = self.cwnd + 1 end
        self.node:log("CONN_ACK ack=%d cwnd=%d ssthresh=%d inflight=%d rto=%.3f",
            ack, self.cwnd, self.ssthresh, count(self.unacked), self.rto)
        self:pump()
    else
        self.dupacks = self.dupacks + 1
        if self.dupacks == 3 then
            local oldest = nil
            for seq, rec in pairs(self.unacked) do
                if not oldest or seq < oldest.seq then oldest = rec end
            end
            if oldest then
                self.ssthresh = math.max(2, floor(self.cwnd / 2))
                self.cwnd = self.ssthresh
                self.retx = self.retx + 1
                self.node:log("CONN_FAST_RETX seq=%d cwnd=%d ssthresh=%d", oldest.seq, self.cwnd, self.ssthresh)
                self:_transmit(oldest)
            end
        end
    end
end

-- handshake blobs (secure mode): authenticated control segments carrying nonces
function Conn:_syn_payload()
    if not self.secure then return "" end
    local head = "C" .. self.nonce_c
    return head .. sec_tag(self, self.k_ctrl, "SYN", u32(self.iss), self.nonce_c)
end

function Conn:_synack_payload()
    if not self.secure then return "" end
    local head = "S" .. self.nonce_s
    return head .. sec_tag(self, self.k_ctrl, "SYNACK", u32(self.iss), self.nonce_c, self.nonce_s)
end

function Conn:_check_syn_payload(payload, seq)
    -- returns true when an authenticated SYN was presented (secure mode)
    if #payload ~= 1 + 8 + self.sec_mac or payload:sub(1, 1) ~= "C" then return false end
    local nc = payload:sub(2, 9)
    local expect = sec_tag(self, self.k_ctrl, "SYN", u32(seq), nc)
    if not M.equals(expect, payload:sub(10, 9 + self.sec_mac)) then return false end
    self.nonce_c = nc
    return true
end

function Conn:_check_synack_payload(payload, seq)
    -- returns "ok" | "bad" | "plaintext"
    if #payload == 0 then return "plaintext" end
    if #payload ~= 1 + 8 + self.sec_mac or payload:sub(1, 1) ~= "S" then return "bad" end
    local ns = payload:sub(2, 9)
    local expect = sec_tag(self, self.k_ctrl, "SYNACK", u32(seq), self.nonce_c, ns)
    if not M.equals(expect, payload:sub(10, 9 + self.sec_mac)) then return "bad" end
    self.nonce_s = ns
    return "ok"
end

function Conn:_on_segment(s, src, sport)
    self.peer_ip, self.peer_port = src, sport
    self.last_activity = os.clock()
    self.ka_miss = 0

    -- secure mode: verify the tag (and decrypt) before touching any state. SYN and
    -- SYN-ACK are excluded: their payloads are handshake blobs authenticated with
    -- k_ctrl (checked in the branches below), not with the session keys.
    if self.secure and self.sec_ready and s.t ~= T_SYN and s.t ~= T_SYNACK then
        local body = sub(s.raw, HDR + 1, HDR + s.len)
        local got = sub(s.raw, HDR + s.len + 1, HDR + s.len + self.sec_mac)
        local expect = sec_tag(self, self.m_rx, sub(s.raw, 1, HDR), body)
        if not M.equals(expect, got) then
            self.sec_drops.auth = self.sec_drops.auth + 1
            self.node:log("CONN_SEC_AUTH_FAIL type=%d from=%s:%d bytes=%d", s.t, int2ip(src), sport, #s.raw)
            return
        end
        if s.len > 0 then
            s.payload = M.chacha20_xor(self.k_rx, self.nonce_rx, s.seq, body)
        else
            s.payload = ""
        end
    end

    if s.t == T_SYN then
        if self.state == "SYN_RCVD" then
            self:_send_ctrl(T_SYNACK, self.iss, self.rcv_nxt, self:_synack_payload())
        end
        return
    end
    if s.t == T_SYNACK then
        if self.state == "SYN_SENT" then
            if self.secure then
                local verdict = self:_check_synack_payload(s.payload, s.seq)
                if verdict == "bad" then
                    self.sec_drops.auth = self.sec_drops.auth + 1
                    self.node:log("CONN_SEC_AUTH_FAIL type=SYNACK from=%s:%d", int2ip(src), sport)
                    return
                elseif verdict == "plaintext" then
                    self.sec_drops.plaintext_peer = self.sec_drops.plaintext_peer + 1
                    self.node:log("CONN_SEC_PEER_PLAINTEXT peer=%s:%d (aborting, fail closed)", int2ip(src), sport)
                    return self:abort("secure peer required")
                end
                sec_derive(self)
            end
            self.rcv_nxt = s.seq + 1
            -- our SYN consumed one sequence number, so data starts at iss+1
            self.snd_una, self.snd_nxt = self.iss + 1, self.iss + 1
            self.dupacks = 0
            self.state = "ESTABLISHED"
            self:_send_ctrl(T_DATA, self.snd_nxt, self.rcv_nxt, "")   -- handshake ACK
            self.node:log("CONN_ESTABLISHED peer=%s:%d", int2ip(src), sport)
            self:start_timer()
            if self.open_cb then self.open_cb(self) end
            self:pump()
        elseif self.state == "ESTABLISHED" then
            -- our ACK got lost: acknowledge the duplicate SYN-ACK again
            self:_send_ctrl(T_DATA, self.snd_nxt, self.rcv_nxt, "")
        end
        return
    end
    if s.t == T_SACK then
        -- selective ACK: mark the covered ranges and retransmit the lowest hole
        local ranges = sack_decode(s.payload)
        self.sack_rx = self.sack_rx + 1
        local covered = 0
        for _, r in ipairs(ranges) do
            for seq, rec in pairs(self.unacked) do
                if seq >= r[1] and seq + #rec.data <= r[2] then
                    rec.sacked = true
                    covered = covered + 1
                end
            end
        end
        if covered > 0 then
            local hole = nil
            for seq, rec in pairs(self.unacked) do
                if not rec.sacked and (not hole or seq < hole.seq) then hole = rec end
            end
            if hole then
                self.ssthresh = math.max(2, floor(self.cwnd / 2))
                self.cwnd = math.max(1, self.ssthresh)
                self.sack_retx = self.sack_retx + 1
                self.retx = self.retx + 1
                self.node:log("CONN_SACK_RETX seq=%d ranges=%d covered=%d cwnd=%d", hole.seq, #ranges, covered, self.cwnd)
                self:_transmit(hole)
            end
        end
        self.node:log("CONN_SACK ranges=%d covered=%d sack_rx=%d", #ranges, covered, self.sack_rx)
        -- an empty SACK doubles as a keepalive probe: answer so the peer knows we live
        if #ranges == 0 then self:_send_ctrl(T_DATA, self.snd_nxt, self.rcv_nxt, "") end
        self:_on_ack(s.ack)
        return
    end
    if s.t == T_FIN then
        self.rcv_nxt = s.seq + 1
        self:_send_ctrl(T_DATA, self.snd_nxt, self.rcv_nxt, "")
        self.state = "CLOSED"
        self.closed = true
        self.node:log("CONN_FIN from=%s bytes_rx=%d", int2ip(src), self.bytes_rx)
        if self.close_cb then self.close_cb(self) end
        return
    end
    if s.t == T_DATA then
        -- peer's advertised window (may be scaled; conn_wscale must match on both ends)
        if s.win then
            self.peer_rwnd = s.win * 2 ^ (self.wscale or 0)
        end
        if s.len > 0 then
            if s.seq == self.rcv_nxt then
                self.rcv_nxt = self.rcv_nxt + s.len
                self.bytes_rx = self.bytes_rx + s.len
                if self.data_cb then self.data_cb(self, s.payload) end
                -- drain anything we buffered while this hole was open
                local progress = true
                while progress do
                    progress = false
                    local buffered = self.ooo[self.rcv_nxt]
                    if buffered then
                        self.ooo[self.rcv_nxt] = nil
                        self.rcv_nxt = self.rcv_nxt + #buffered
                        self.bytes_rx = self.bytes_rx + #buffered
                        if self.data_cb then self.data_cb(self, buffered) end
                        progress = true
                    end
                end
            elseif s.seq > self.rcv_nxt then
                -- out of order: buffer it (selective ACK) and report what we have
                if self.sack and not self.ooo[s.seq] then
                    self.ooo[s.seq] = s.payload
                    self.ooo_bytes = self.ooo_bytes + #s.payload
                    self.ooo_buffered = self.ooo_buffered + 1
                end
                self.dup_rx = self.dup_rx + 1
                self.node:log("CONN_OOO_SEG seq=%d expected=%d buffered=%d (dup ack)", s.seq, self.rcv_nxt, self.ooo_buffered)
                if self.sack then self:_send_sack() end
            else
                self.dup_rx = self.dup_rx + 1
                self.node:log("CONN_OOO_SEG seq=%d expected=%d (old duplicate)", s.seq, self.rcv_nxt)
            end
            self:_send_ctrl(T_DATA, self.snd_nxt, self.rcv_nxt, "")
        end
        -- handshake completion is signalled by the peer's first ACK, which may
        -- be a pure ACK (no payload) or arrive piggybacked on data
        if self.state == "SYN_RCVD" and s.ack and s.ack >= self.snd_nxt then
            self.state = "ESTABLISHED"
            self.node:log("CONN_ACCEPTED peer=%s:%d", int2ip(src), sport)
            if self.listener and self.listener.on_accept then self.listener.on_accept(self) end
            if self.open_cb then self.open_cb(self) end
        end
        self:_on_ack(s.ack)
    end
end

-- report the contiguous blocks we hold out of order so the sender retransmits only
-- the hole (selective ACK)
function Conn:_send_sack()
    local seqs = {}
    for seq in pairs(self.ooo) do seqs[#seqs + 1] = seq end
    table.sort(seqs)
    local ranges = {}
    for _, seq in ipairs(seqs) do
        local right = seq + #self.ooo[seq]
        local last = ranges[#ranges]
        if last and seq <= last[2] then
            if right > last[2] then last[2] = right end
        else
            ranges[#ranges + 1] = { seq, right }
        end
    end
    self.sack_sent = self.sack_sent + 1
    self.node:log("CONN_SACK_SENT ranges=%d rcv_nxt=%d buffered=%d", #ranges, self.rcv_nxt, self.ooo_buffered)
    return self:_send_ctrl(T_SACK, self.snd_nxt, self.rcv_nxt, sack_encode(ranges))
end

function Conn:_finish_close()
    self.fin_sent = true
    self:_send_ctrl(T_FIN, self.snd_nxt, self.rcv_nxt, "")
    self.node:log("CONN_FIN_SENT bytes_tx=%d tx=%d retx=%d", self.bytes_tx, self.tx, self.retx)
end

function Conn:close()
    if self.state == "ESTABLISHED" then
        self.close_pending = true
        self:pump()
    elseif self.state == "SYN_SENT" then
        self.closed = true
    end
end

function Conn:abort(why)
    -- give the in-flight segments of this connection back to the node-wide counter
    self.node.conn_inflight = math.max(0, (self.node.conn_inflight or 0) - count(self.unacked))
    self.unacked = {}
    self.state = "CLOSED"
    self.closed = true
    self.node:log("CONN_ABORT %s", tostring(why))
    if self.close_cb then self.close_cb(self) end
end

function Conn:log_stats(tag)
    self.node:log("CONN_STATS %s cwnd=%d ssthresh=%d srtt=%s rto=%.3f tx=%d retx=%d dupacks=%d out_of_order=%d bytes_tx=%d bytes_rx=%d secure=%s sec_auth_fail=%d sec_ctrl=%d sec_plaintext=%d",
        tostring(tag), self.cwnd, self.ssthresh,
        self.srtt and string.format("%.3f", self.srtt) or "?", self.rto,
        self.tx, self.retx, self.dupacks, self.dup_rx, self.bytes_tx, self.bytes_rx,
        tostring(self.secure), self.sec_drops.auth, self.sec_drops.ctrl, self.sec_drops.plaintext_peer)
    self.node:log("CONN_P3 sack_rx=%d sack_sent=%d sack_retx=%d ooo_buffered=%d ooo_bytes=%d keepalives=%d rwnd=%d wscale=%d peer_rwnd=%s gmax=%d",
        self.sack_rx, self.sack_sent, self.sack_retx, self.ooo_buffered, self.ooo_bytes,
        self.keepalives, self.rwnd, self.wscale, tostring(self.peer_rwnd), self.gmax)
end

function Conn:start_timer()
    if self.closed then return end
    self.node:after(0.05, function() self:_tick() end)
end

function Conn:_tick()
    if self.closed or self.state == "CLOSED" then return end
    local now = os.clock()
    -- control segments (SYN / SYN-ACK) retransmission
    if self.state == "SYN_SENT" or self.state == "SYN_RCVD" then
        self.syn_tries = (self.syn_tries or 1)
        if not self.syn_t0 then self.syn_t0 = now end
        if now - self.syn_t0 >= self.rto then
            if self.syn_tries >= 6 then
                return self:abort("handshake timeout")
            end
            self.syn_tries = self.syn_tries + 1
            self.syn_t0 = now
            self.rto = math.min(self.rto * 2, self.rto_max or 2.0)
            local t = (self.state == "SYN_SENT") and T_SYN or T_SYNACK
            local payload = (t == T_SYN) and self:_syn_payload() or self:_synack_payload()
            self:_send_ctrl(t, self.iss, self.rcv_nxt, payload)
            self.node:log("CONN_HANDSHAKE_RETX type=%d try=%d rto=%.3f", t, self.syn_tries, self.rto)
        end
    end
    -- keepalive: probe when idle, give up after 3 unanswered probes
    if self.keepalive > 0 and self.state == "ESTABLISHED" then
        local idle = now - (self.last_activity or now)
        if idle >= self.keepalive then
            self.keepalives = self.keepalives + 1
            self.ka_miss = (self.ka_miss or 0) + 1
            self.last_activity = now
            if self.ka_miss > 3 then
                self.node:log("CONN_KEEPALIVE_TIMEOUT misses=%d probes=%d", self.ka_miss, self.keepalives)
                return self:abort("keepalive timeout")
            end
            self.node:log("CONN_KEEPALIVE probe=%d idle=%.2fs miss=%d", self.keepalives, idle, self.ka_miss)
            self:_send_ctrl(T_SACK, self.snd_nxt, self.rcv_nxt, u8(0))
        end
    end
    -- data retransmission (RTO with AIMD collapse)
    for seq, rec in pairs(self.unacked) do
        if rec.t0 and now - rec.t0 >= self.rto then
            if rec.tries >= 6 then return self:abort("data timeout seq=" .. tostring(seq)) end
            self.ssthresh = math.max(2, floor(self.cwnd / 2))
            self.cwnd = 1
            self.retx = self.retx + 1
            self.rto = math.min(self.rto * 2, self.rto_max or 2.0)
            self.node:log("CONN_RTO seq=%d rto=%.3f cwnd=1 ssthresh=%d retx=%d", seq, self.rto, self.ssthresh, self.retx)
            self:_transmit(rec)
            self:pump()
            break
        end
    end
    self:start_timer()
end

function M.conn_connect(node, ip, port, opts)
    opts = opts or {}
    local c = M.conn_new(node, {
        port = opts.sport or port, peer_ip = ip, peer_port = port, state = "SYN_SENT",
    })
    c:_send_ctrl(T_SYN, c.iss, 0, c:_syn_payload())
    c.snd_nxt = c.iss + 1              -- the SYN itself consumes one sequence number
    c.syn_tries, c.syn_t0 = 1, os.clock()
    c:_bind()
    c:start_timer()
    node:log("CONN_SYN_SENT peer=%s:%d iss=%d secure=%s", int2ip(ip), port, c.iss, tostring(c.secure))
    return c
end

function Conn:_bind()
    self.sk = self.node:bind(self.port, function(data, src, sport)
        local s = M.conn_parse(data)
        if not s then
            self.node:log("CONN_BAD_SEG from=%s bytes=%d", int2ip(src), #data)
            return
        end
        self:_on_segment(s, src, sport)
    end)
end

function M.conn_listen(node, port, on_accept)
    local l = { node = node, port = port, on_accept = on_accept, conns = {} }
    l.sk = node:bind(port, function(data, src, sport)
        local s = M.conn_parse(data)
        if not s then
            node:log("CONN_BAD_SEG from=%s bytes=%d", int2ip(src), #data)
            return
        end
        local key = src .. ":" .. sport
        local c = l.conns[key]
        if not c and s.t == T_SYN then
            c = M.conn_new(node, { port = port, peer_ip = src, peer_port = sport, state = "SYN_RCVD" })
            if c.secure and not c:_check_syn_payload(s.payload, s.seq) then
                c.sec_drops.ctrl = c.sec_drops.ctrl + 1
                node:log("CONN_SEC_SYN_REJECT from=%s:%d (unauthenticated SYN)", int2ip(src), sport)
                return
            end
            c.listener = l
            l.conns[key] = c
            c.rcv_nxt = s.seq + 1
            c:_send_ctrl(T_SYNACK, c.iss, c.rcv_nxt, c:_synack_payload())
            c.snd_nxt = c.iss + 1          -- SYN-ACK consumed one sequence number
            if c.secure then sec_derive(c) end
            c.syn_tries, c.syn_t0 = 1, os.clock()
            c:start_timer()
            node:log("CONN_SYN_RCVD from=%s:%d iss=%d secure=%s", int2ip(src), sport, c.iss, tostring(c.secure))
        elseif c then
            c:_on_segment(s, src, sport)
        else
            node:log("CONN_NO_SYN type=%d from=%s:%d", s.t, int2ip(src), sport)
        end
    end)
    return l
end

return M
]==],
    fabric = [==[
--[[- rpv/fabric.lua ? cluster: several computers acting as one logical router.

Ported from the monolithic prototype into the module library. Members announce
their real interfaces over a shared fabric channel (unicast frames go to the
target member's own ID channel, so only its modem is woken), build remote routes
from those announcements, and hand packets over with FAB_FORWARD so the egress
member transmits them at that segment's MTU. TTL is decremented ONCE per
cluster, i.e. N members count as one router hop.

All offsets here are relative to the L2 body (link_parse has already stripped
the 10-byte frame header).
]]
local M = ...
local u8, u16, u32, r16, r32, byte, sub, int2ip = M.u8, M.u16, M.u32, M.r16, M.r32, M.byte, M.sub, M.int2ip

local ET_FABRIC = 0x88B5
local FAB_ANNOUNCE, FAB_FORWARD, FAB_FRAG = 1, 2, 3
M.ET_FABRIC = ET_FABRIC

function M.fabric_new(side, channel, mtu)
    return {
        side = side, channel = tonumber(channel), mtu = tonumber(mtu) or 1024,
        peers = {}, routes = {}, ucast = nil, iface = nil, announces = 0,
        seq = 0, peer_seq = {}, frags = {}, frag_bytes = 0, fragid = 0,
    }
end

function M.fabric_setup(node, f)
    f.ucast = node.id % 65500
    f.iface = {
        side = f.side, name = "FAB", channel = f.channel, mtu = f.mtu,
        is_fabric = true, ip = 0, prefix = 0, net = 0, cidr = "-",
    }
    if peripheral.getType(f.side) ~= "modem" then
        node:log("FABRIC_NO_MODEM side=%s", f.side)
        return false
    end
    peripheral.call(f.side, "open", f.channel)
    peripheral.call(f.side, "open", f.ucast)
    node.by_channel[f.channel] = f.iface
    node.by_channel[f.ucast] = f.iface
    node:log("FABRIC side=%s bcast_ch=%d ucast_ch=%d mtu=%d", f.side, f.channel, f.ucast, f.mtu)
    return true
end

function M.fabric_send_frame(node, f, dstmac, body)
    peripheral.call(f.side, "transmit", f.channel, node.mac,
        u32(dstmac) .. u32(node.mac) .. u16(ET_FABRIC) .. body)
    node.stats.fabric_frames = (node.stats.fabric_frames or 0) + 1
end

function M.fabric_announce(node, f)
    f.seq = f.seq + 1
    local body = u8(FAB_ANNOUNCE) .. u16(f.seq) .. u8(#node.ifaces)
    for _, i in ipairs(node.ifaces) do
        body = body .. u8(#i.cidr) .. i.cidr .. u8(#i.name) .. i.name
    end
    M.fabric_send_frame(node, f, M.MAC_BCAST, body)
    f.announces = f.announces + 1
    node:log("FABRIC_ANNOUNCE sent ifaces=%d seq=%d", #node.ifaces, f.seq)
end

-- FAB_FORWARD body: cmd(1) idx(1) ttl(1) proto(1) src(4) dst(4) payload
-- FAB_FRAG   body: ... + fragid(2) off8(2) mf(1) chunk
local FRAG_HEADER = 17

function M.fabric_forward(node, f, member, idx, src, dst, proto, ttl, payload)
    local maxpay = f.mtu - 10 - 12
    if #payload <= maxpay then
        local body = u8(FAB_FORWARD) .. u8(idx) .. u8(ttl) .. u8(proto) .. u32(src) .. u32(dst) .. payload
        M.fabric_send_frame(node, f, member, body)
        node.stats.fabric_fwd = (node.stats.fabric_fwd or 0) + 1
        node:log("FABRIC_FWD member=%d idx=%d ttl=%d proto=%d bytes=%d", member, idx, ttl, proto, #payload)
        return true
    end
    -- payload does not fit a single fabric frame: fragment it
    f.fragid = f.fragid % 65535 + 1
    local chunkmax = f.mtu - 10 - FRAG_HEADER
    chunkmax = chunkmax - (chunkmax % 8)
    if chunkmax <= 0 then
        node:log("FABRIC_MTU_TOO_SMALL mtu=%d", f.mtu)
        return false
    end
    local parts = 0
    for off = 0, #payload - 1, chunkmax do
        local chunk = sub(payload, off + 1, math.min(off + chunkmax, #payload))
        local mf = (off + #chunk) < #payload
        local body = u8(FAB_FRAG) .. u8(idx) .. u8(ttl) .. u8(proto) .. u32(src) .. u32(dst)
            .. u16(f.fragid) .. u16(off / 8) .. u8(mf and 1 or 0) .. chunk
        M.fabric_send_frame(node, f, member, body)
        parts = parts + 1
    end
    node.stats.fabric_frag_tx = (node.stats.fabric_frag_tx or 0) + parts
    node:log("FABRIC_FRAG_TX member=%d id=%d bytes=%d parts=%d mtu=%d", member, f.fragid, #payload, parts, f.mtu)
    return true
end

function M.fabric_announce_loop(node, f)
    M.fabric_announce(node, f)
    node:after(tonumber(node.cfg.fabric_interval) or 2, function() M.fabric_announce_loop(node, f) end)
end

function M.fabric_input(node, f, body, srcmac)
    local cmd = byte(body, 1)
    if cmd == FAB_ANNOUNCE then
        local seq, n, pos, list = r16(body, 2), byte(body, 4), 5, {}
        local last = f.peer_seq[srcmac]
        if last and seq <= last then
            node.stats.fabric_announce_stale = (node.stats.fabric_announce_stale or 0) + 1
            node:log("FABRIC_ANNOUNCE_STALE member=%d seq=%d <= %d (ignored)", srcmac, seq, last)
            return
        end
        f.peer_seq[srcmac] = seq
        for i = 1, n do
            local cl = byte(body, pos)
            local cidr = sub(body, pos + 1, pos + cl)
            pos = pos + 1 + cl
            local nl = byte(body, pos)
            local name = sub(body, pos + 1, pos + nl)
            pos = pos + 1 + nl
            list[i] = { cidr = cidr, name = name }
        end
        f.peers[srcmac] = { ifaces = list, expires = os.clock() + 6 }
        M.fabric_rebuild_routes(node, f)
        node:log("FABRIC_ANNOUNCE member=%d seq=%d ifaces=%s", srcmac, seq, list[1] and list[1].cidr or "?")
    elseif cmd == FAB_FORWARD then
        local idx, ttl, proto = byte(body, 2), byte(body, 3), byte(body, 4)
        local src, dst = r32(body, 5), r32(body, 9)
        local data = sub(body, 13)
        local iface = node.ifaces[idx]
        if not iface then
            node:log("FABRIC_BAD_IDX idx=%d from=%d", idx, srcmac)
            return
        end
        node.stats.fabric_recv = (node.stats.fabric_recv or 0) + 1
        node:log("FABRIC_RECV fromMember=%d out=%s ttl=%d proto=%d bytes=%d", srcmac, iface.name, ttl, proto, #data)
        -- verbatim hand-off: no second TTL decrement, no re-route; the egress
        -- member ARPs for the real destination on its own segment
        node:send_local(iface, dst, src, dst, proto, ttl, data)
    elseif cmd == FAB_FRAG then
        local idx, ttl, proto = byte(body, 2), byte(body, 3), byte(body, 4)
        local src, dst = r32(body, 5), r32(body, 9)
        local fragid, off8, mf = r16(body, 13), r16(body, 15), byte(body, 17) == 1
        local chunk = sub(body, 18)
        local key = srcmac .. ":" .. fragid
        local b = f.frags[key]
        if not b then
            local count = 0
            for _ in pairs(f.frags) do count = count + 1 end
            if count >= 8 then
                node.stats.fabric_frag_drops = (node.stats.fabric_frag_drops or 0) + 1
                node:log("FABRIC_FRAG_DROP table full (key=%s)", key)
                return
            end
            b = { parts = {}, expires = os.clock() + 5, idx = idx, ttl = ttl, proto = proto, src = src, dst = dst }
            f.frags[key] = b
        end
        b.parts[#b.parts + 1] = { off = off8 * 8, data = chunk }
        f.frag_bytes = f.frag_bytes + #chunk
        if not mf then b.total = off8 * 8 + #chunk end
        if not b.total then return end
        table.sort(b.parts, function(x, y) return x.off < y.off end)
        local pos, out = 0, {}
        for _, p in ipairs(b.parts) do
            if p.off ~= pos then return end
            out[#out + 1] = p.data
            pos = pos + #p.data
        end
        if pos ~= b.total then return end
        f.frags[key] = nil
        f.frag_bytes = f.frag_bytes - pos
        node.stats.fabric_frag_rx = (node.stats.fabric_frag_rx or 0) + 1
        node:log("FABRIC_FRAG_RX fromMember=%d id=%d bytes=%d parts=%d", srcmac, fragid, pos, #b.parts)
        local iface = node.ifaces[b.idx]
        if not iface then
            node:log("FABRIC_BAD_IDX idx=%d from=%d", b.idx, srcmac)
            return
        end
        node:send_local(iface, b.dst, b.src, b.dst, b.proto, b.ttl, M.concat(out))
    else
        node:log("FABRIC_UNKNOWN_CMD %d", cmd)
    end
end

function M.fabric_rebuild_routes(node, f)
    local out = {}
    for member, p in pairs(f.peers) do
        if p.expires > os.clock() then
            for i, meta in ipairs(p.ifaces) do
                local ipstr, prefix = meta.cidr:match("^([%d%.]+)/(%d+)$")
                if ipstr then
                    out[#out + 1] = {
                        prefix = tonumber(prefix), net = M.masked(M.ip2int(ipstr), tonumber(prefix)),
                        remote = member, idx = i, meta = meta,
                    }
                end
            end
        end
    end
    f.routes = out
end

function M.fabric_tick(node, f)
    local expired = false
    for member, p in pairs(f.peers) do
        if p.expires < os.clock() then
            f.peers[member] = nil
            expired = true
            node:log("FABRIC_PEER_EXPIRED member=%d", member)
        end
    end
    if expired then M.fabric_rebuild_routes(node, f) end
    local now = os.clock()
    for key, b in pairs(f.frags) do
        if b.expires < now then
            for _, p in ipairs(b.parts) do f.frag_bytes = f.frag_bytes - #p.data end
            f.frags[key] = nil
            node.stats.fabric_frag_drops = (node.stats.fabric_frag_drops or 0) + 1
            node:log("FABRIC_FRAG_TIMEOUT key=%s", key)
        end
    end
end

return M
]==],
    wan = [==[
--[[- rpv/wan.lua ? rednet as the WAN interface only.

Ported from the monolithic prototype. The WAN interface's link layer IS rednet:
frames are handed to rednet.send(<peer id>, frame, "rpv") and arrive as
rednet_message. Routers advertise their connected subnets ({"rpv-advert"}),
peers learn WAN routes from those, plain rednet devices are reached through
static map= entries with UDP<->table translation. Nothing here is used for LAN
traffic: rednet.open() is only ever called on the WAN modem.
]]
local M = ...
local u8, u16, u32, r16, r32, byte, sub, floor, int2ip = M.u8, M.u16, M.u32, M.r16, M.r32, M.byte, M.sub, M.floor, M.int2ip

function M.wan_new(side, mtu)
    return {
        side = side, channel = "wan", mtu = tonumber(mtu) or 512,
        is_wan = true, peers = {}, routes = {}, legacy = {},
        advert = 0, legacy_tx = 0, legacy_rx = 0, sent_frames = 0, recv_frames = 0,
        seq = 0, advert_seq = {},
        iface = { side = side, name = "WAN", channel = "wan", is_wan = true, ip = 0, prefix = 0, mtu = tonumber(mtu) or 512 },
    }
end

function M.wan_setup(node, w, cidr)
    w.iface.cidr = cidr
    -- the WAN interface gets a connected route for its own subnet, exactly like a LAN
    -- interface: directly attached WAN peers are then reachable without waiting for an
    -- advert (needed by the minimal "WAN only" topology and by WAN-only nodes)
    local ipstr, prefix = tostring(cidr):match("^([%d%.]+)/(%d+)$")
    if ipstr then
        w.iface.ip = M.ip2int(ipstr)
        w.iface.prefix = tonumber(prefix)
        w.iface.net = M.masked(w.iface.ip, w.iface.prefix)
        if M.route_connected then M.route_connected(node.routes, w.iface) end
    end
    if peripheral.getType(w.side) ~= "modem" then
        node:log("WAN_NO_MODEM side=%s", w.side)
        return false
    end
    rednet.open(w.side)
    node.by_channel["wan"] = w.iface
    -- static WAN neighbours (wan_peer=172.16.0.2:22[,more]): a directly attached peer can
    -- be pinned so the first packet does not have to wait for an advert or a hello to
    -- teach us its rednet id (the wired/wireless equivalent of a static ARP entry)
    for spec in tostring(node.cfg.wan_peer or ""):gmatch("[^,]+") do
        local pip, pid = spec:match("^%s*([%d%.]+)%s*:%s*(%d+)%s*$")
        if pip and pid then
            w.peers[pip] = tonumber(pid)
            node:log("WAN_PEER_STATIC ip=%s id=%s", pip, pid)
        end
    end
    -- both wired and wireless modems are accepted: rednet.open works on either, and
    -- nothing here assumes wireless (the router needs the peer on the same wired
    -- network, or within wireless range)
    local ptype = peripheral.getType(w.side)
    local pwireless = nil
    if ptype == "modem" then
        local okw, v = pcall(peripheral.call, w.side, "isWireless")
        pwireless = okw and v or nil
    end
    node:log("WAN_READY side=%s addr=%s mtu=%d advertise=%s peripheral=%s phys_wireless=%s",
        w.side, w.iface.cidr, w.mtu, tostring(node.cfg.advert == "1"), tostring(ptype), tostring(pwireless))
    if node.cfg.rpv_host then
        rednet.host("rpv", node.cfg.rpv_host)
        node:log("WAN_REDNET_HOST protocol=rpv name=%s", node.cfg.rpv_host)
    end
    if node.cfg.advert == "1" then node:after(1.0, function() M.wan_advert_loop(node, w) end) end
    -- WAN tunnel AEAD (wansec.lua): opt-in with wan_secure=1
    if node.cfg.wan_secure == "1" and M.wansec_setup then
        M.wansec_setup(node, w)
        node:after(1.5, function() M.wansec_hello_loop(node, w) end)
    end
    return true
end

function M.wan_frame_send(node, w, peer, pkt)
    local frame = u32(peer) .. u32(node.mac) .. u16(M.ET_IP) .. pkt
    if node.wansec and node.wansec.enabled then
        local env = M.wansec_wrap(node, w, peer, frame)
        if not env then
            w.sec_dropped = (w.sec_dropped or 0) + 1
            return false                      -- fail closed: no keys, no frame
        end
        rednet.send(peer, env, "rpv")
    else
        rednet.send(peer, frame, "rpv")
    end
    w.sent_frames = w.sent_frames + 1
    return true
end

-- path = { peer = rednet id, peer_ip = rpv ip, legacy = bool }
function M.wan_send(node, w, path, src, dst, proto, ttl, payload)
    if not path.peer then
        node.stats.wan_no_peer = (node.stats.wan_no_peer or 0) + 1
        node:log("WAN_NO_PEER dst=%s (no rednet id known yet)", int2ip(dst))
        return false
    end
    if path.legacy then
        if proto ~= M.IP_UDP then
            node:log("WAN_LEGACY_UNSUPPORTED proto=%d dst=%s", proto, int2ip(dst))
            return false
        end
        local sport, dport, data = r16(payload, 1), r16(payload, 3), sub(payload, 9)
        if #data + 8 > w.mtu then
            node:log("WAN_LEGACY_TOO_BIG bytes=%d mtu=%d", #data, w.mtu)
            return false
        end
        w.legacy_tx = w.legacy_tx + 1
        node:log("WAN_LEGACY_TX peer=%d to=%s sport=%d dport=%d bytes=%d", path.peer, int2ip(dst), sport, dport, #data)
        rednet.send(path.peer, {
            sType = "udp", from = int2ip(src), to = int2ip(dst),
            sport = sport, dport = dport, data = data,
        }, "rpv")
        return true
    end
    local id = node:next_ipid()
    local maxpay = w.mtu - 20
    maxpay = maxpay - (maxpay % 8)
    local frames = 0
    if #payload <= maxpay then
        M.wan_frame_send(node, w, path.peer, M.ip_build(src, dst, proto, ttl, id, false, 0, payload))
        frames = 1
    else
        for off = 0, #payload - 1, maxpay do
            local chunk = sub(payload, off + 1, math.min(off + maxpay, #payload))
            local mf = (off + #chunk) < #payload
            M.wan_frame_send(node, w, path.peer, M.ip_build(src, dst, proto, ttl, id, mf, off / 8, chunk))
            frames = frames + 1
        end
        node:log("WAN_FRAGMENTED id=%d bytes=%d frames=%d mtu=%d", id, #payload, frames, w.mtu)
    end
    node.stats.wan_sent = (node.stats.wan_sent or 0) + frames
    node:log("WAN_SENT peer=%d dst=%s proto=%d ttl=%d bytes=%d frames=%d", path.peer, int2ip(dst), proto, ttl, #payload, frames)
    return true
end

function M.wan_input(node, w, sender, message, protocol)
    if protocol ~= "rpv" then return end
    -- WAN AEAD: unwrap encrypted frames, verify signed control tables
    if node.wansec then
        if type(message) == "table" and message.sType == "rpv-sec-hello" then
            return M.wansec_hello_input(node, w, sender, message)
        end
        if type(message) == "string" then
            if sub(message, 1, 1) == "S" then
                local plain = M.wansec_unwrap(node, w, sender, message)
                if not plain then return end
                message = plain
            elseif node.wansec.enabled then
                node.wansec.plaintext = node.wansec.plaintext + 1
                node:log("WANSEC_PLAINTEXT data frame from=%s bytes=%d (dropped, fail closed)", tostring(sender), #message)
                return
            end
        elseif type(message) == "table" then
            if not M.wansec_verify_table(node, w, sender, message) then return end
        end
    end
    if type(message) == "string" and #message >= 10 then
        local srcmac = r32(message, 5)
        if srcmac ~= sender then node:log("WAN_SPOOF frame_srcmac=%d rednet_sender=%s", srcmac, tostring(sender)) end
        node.stats.wan_recv = (node.stats.wan_recv or 0) + 1
        w.recv_frames = w.recv_frames + 1
        local h = M.ip_parse(sub(message, 11))
        if h then
            w.peers[h.src] = sender
            w.peer_seen = w.peer_seen or {}
            w.peer_seen[h.src] = os.clock() + 9
        end
        node:log("WAN_RECV from=%s bytes=%d", tostring(sender), #message)
        return node:on_frame(w.iface, message)
    end
    if type(message) ~= "table" then return end
    if message.sType == "rpv-advert" then return M.wan_advert_input(node, w, sender, message) end
    if message.sType == "rpv-is-at" then
        local ip = type(message.ip) == "string" and M.ip2int(message.ip) or nil
        if ip then
            w.peers[ip] = tonumber(message.id) or sender
            w.peer_seen = w.peer_seen or {}
            w.peer_seen[ip] = os.clock() + 9
        end
        node:log("WAN_IS_AT ip=%s id=%s", tostring(message.ip), tostring(message.id))
        return
    end
    if message.sType == "rpv-who-has" then return M.wan_who_has(node, w, sender, message) end
    if message.sType == "udp" then return M.wan_legacy_rx(node, w, sender, message) end
    node:log("WAN_CTRL_UNKNOWN type=%s", tostring(message.sType))
end

function M.wan_advert(node, w)
    local nets = {}
    for _, i in ipairs(node.ifaces) do
        -- advertise LANs only: the WAN subnet itself is not a remote network
        if not i.is_wan then nets[#nets + 1] = i.cidr end
    end
    w.seq = w.seq + 1
    local advert = {
        sType = "rpv-advert", ver = 1, seq = w.seq, hops = 1,
        gw = node.mac, ip = int2ip(w.iface.ip), nets = nets,
        default = node.cfg.advert_default == "1" and 1 or nil,
    }
    if M.wansec_sign_table then M.wansec_sign_table(node, advert) end
    rednet.broadcast(advert, "rpv")
    w.advert = w.advert + 1
    node:log("WAN_ADVERT_SENT ip=%s nets=%d seq=%d default=%s", int2ip(w.iface.ip), #nets, w.seq,
        tostring(node.cfg.advert_default == "1"))
end

function M.wan_advert_loop(node, w)
    M.wan_advert(node, w)
    node:after(tonumber(node.cfg.advert_interval) or 3, function() M.wan_advert_loop(node, w) end)
end

function M.wan_advert_input(node, w, sender, message)
    local gid = tonumber(message.gw) or sender
    local gwip = type(message.ip) == "string" and M.ip2int(message.ip) or nil
    -- loop protection: an advert that travelled too far is ignored
    local hops = tonumber(message.hops) or 1
    local max_hops = tonumber(node.cfg.max_advert_hops) or 4
    if hops > max_hops then
        node:log("WAN_ADVERT_LOOP gw=%d hops=%d > max %d (ignored)", gid, hops, max_hops)
        return
    end
    -- sequence check: reordered/duplicated adverts are ignored
    local seq = tonumber(message.seq)
    if seq then
        local last = w.advert_seq[gid]
        if last and seq <= last then
            node.stats.wan_advert_stale = (node.stats.wan_advert_stale or 0) + 1
            node:log("WAN_ADVERT_STALE gw=%d seq=%d <= %d (ignored)", gid, seq, last)
            return
        end
        w.advert_seq[gid] = seq
    end
    if gwip then
        w.peers[gwip] = gid
        w.peer_seen = w.peer_seen or {}
        w.peer_seen[gwip] = os.clock() + 9
    end
    local added, nets = 0, message.nets or {}
    for _, netstr in ipairs(nets) do
        local ip, prefix = tostring(netstr):match("^([%d%.]+)/(%d+)$")
        if ip then
            local pn = tonumber(prefix)
            local net = M.masked(M.ip2int(ip), pn)
            local mine = false
            for _, i in ipairs(node.ifaces) do
                if i.net == net and i.prefix == pn then mine = true end
            end
            if not mine and gid ~= node.mac then
                w.routes[string.format("%s/%d", int2ip(net), pn)] =
                    { prefix = pn, net = net, wan = true, gw_id = gid, gw_ip = gwip, expires = os.clock() + 9 }
                added = added + 1
            end
        end
    end
    -- optional default route: only installed when this site has no static gateway
    if message.default == 1 and gwip and not node.cfg.gw and gid ~= node.mac then
        w.routes["0.0.0.0/0"] = { prefix = 0, net = 0, wan = true, gw_id = gid, gw_ip = gwip, expires = os.clock() + 9 }
        node:log("WAN_DEFAULT_ROUTE gw=%d via=%s", gid, int2ip(gwip))
    end
    node:log("WAN_ADVERT_RECV gw=%d ip=%s seq=%s nets=%d added=%d", gid, tostring(message.ip), tostring(seq), #nets, added)
end

function M.wan_who_has(node, w, sender, message)
    local ip = type(message.ip) == "string" and M.ip2int(message.ip) or nil
    if not ip then return end
    local mine = false
    for _, i in ipairs(node.ifaces) do
        if i.ip == ip then mine = true end
    end
    node:log("WAN_WHO_HAS from=%s ip=%s answer=%s", tostring(sender), int2ip(ip), tostring(mine))
    if mine then
        local reply = { sType = "rpv-is-at", ip = int2ip(ip), id = node.mac }
        if M.wansec_sign_table then M.wansec_sign_table(node, reply) end
        rednet.send(sender, reply, "rpv")
    end
end

function M.wan_legacy_rx(node, w, sender, message)
    local dst = type(message.to) == "number" and message.to or M.ip2int(message.to)
    local sport = tonumber(message.sport) or 0
    local dport = tonumber(message.dport) or 0
    local data = tostring(message.data or "")
    w.legacy_rx = w.legacy_rx + 1
    node:log("WAN_LEGACY_RX from_rednet=%s to=%s sport=%d dport=%d bytes=%d", tostring(sender), int2ip(dst), sport, dport, #data)
    M.udp_send(node, dst, sport, dport, data, 64)
end

function M.wan_tick(node, w)
    local now = os.clock()
    for key, r in pairs(w.routes) do
        if r.expires < now then
            w.routes[key] = nil
            node:log("WAN_ROUTE_EXPIRED net=%s", key)
        end
    end
    if w.peer_seen then
        for ip, exp in pairs(w.peer_seen) do
            if exp < now and not w.legacy[ip] then
                w.peers[ip] = nil
                w.peer_seen[ip] = nil
            end
        end
    end
end

return M
]==],
    services = [==[
--[[- rpv/services.lua ? DHCP-lite (address autoconfiguration) and lookup-lite (name?IP).

Both are ordinary rpv UDP services, so they work across routers and the rednet WAN
like any other traffic.

DHCP-LITE (UDP 6700 by default)
  A client starts with a *placeholder* address on the segment the server lives on
  (convention: `dhcp=1` with a cidr in 10.254.0.0/16), broadcasts DISCOVER, and
  adopts the address the server offers:

      DISCOVER (broadcast)  -> OFFER  (unicast, offered ip/mask/gw/dns/lease)
      REQUEST  (unicast)    -> ACK    (unicast; the lease is committed)
                             -> NAK    (no pool space / bad request)

  On ACK the client re-addresses its interface, installs the default route and (when
  a name is configured) registers that name with the name server.

  server keys: dhcp_pool=10.0.1.100-10.0.1.150  dhcp_gw=10.0.1.1  dhcp_dns=10.0.1.1
               dhcp_lease=600  dhcp_port=6700  dhcp_server_name=dhcp
  client keys: dhcp=1  [dhcp_server=<ip>]  name=<hostname>  dns_server=<ip>

LOOKUP-LITE (UDP 6701 by default)
      REGISTER name -> ip      (client announces itself to the name server)
      QUERY    name -> ANSWER ip / NACK
  Clients also read a static `hosts.txt` (`<name> <ip>` per line) at setup, so the
  common case needs no query at all.

  server keys: dns=1  dns_port=6701
  client keys: name=<hostname>  dns_server=<ip>  (defaults to the default gateway)

Wire format (kept tiny on purpose):
  DHCP:  u8 type | u32 xid | u32 ip | u8 prefix | u32 gw | u32 dns | u32 lease | u8 nameLen | name
  DNS:   u8 type | u8 nameLen | name | u32 ip
]]
local M = ...
local u8, u16, u32, r32, byte, sub = M.u8, M.u16, M.u32, M.r32, M.byte, M.sub

local DHCP_PORT, DNS_PORT = 6700, 6701
local T_DISCOVER, T_OFFER, T_REQUEST, T_ACK, T_NAK = 1, 2, 3, 4, 5
local T_RELEASE, T_DECLINE = 6, 7
local D_REGISTER, D_QUERY, D_ANSWER, D_NACK = 1, 2, 3, 4

M.SERVICES_TYPES = {
    dhcp = { DISCOVER = T_DISCOVER, OFFER = T_OFFER, REQUEST = T_REQUEST, ACK = T_ACK, NAK = T_NAK },
    dns = { REGISTER = D_REGISTER, QUERY = D_QUERY, ANSWER = D_ANSWER, NACK = D_NACK },
}

-- ===== DHCP-lite ============================================================
-- wire format: 1 type | 4 xid | 4 ip | 1 prefix | 4 gw | 4 dns | 4 lease |
--               4 server-id | 4 client-id (mac) | 1 nameLen | name
--
-- The client id (its mac) is what leases are keyed on: keying on the source address
-- collides when two clients still hold the same placeholder address. server-id lets a
-- client address its REQUEST/RELEASE at the server that offered the lease.
local D_MIN = 31
local function dhcp_pack(t, xid, ip, prefix, gw, dns, lease, server, client, name)
    name = name or ""
    return u8(t) .. u32(xid or 0) .. u32(ip or 0) .. u8(prefix or 0) .. u32(gw or 0)
        .. u32(dns or 0) .. u32(lease or 0) .. u32(server or 0) .. u32(client or 0)
        .. u8(#name) .. name
end

local function dhcp_unpack(s)
    if #s < D_MIN then return nil end
    local nl = byte(s, 31)
    if #s < D_MIN + nl then return nil end
    return {
        t = byte(s, 1), xid = r32(s, 2), ip = r32(s, 6), prefix = byte(s, 10),
        gw = r32(s, 11), dns = r32(s, 15), lease = r32(s, 19),
        server = r32(s, 23), client = r32(s, 27), name = sub(s, 32, 31 + nl),
    }
end
M.dhcp_pack, M.dhcp_unpack = dhcp_pack, dhcp_unpack

-- A client that has no address yet may not be routable at all, so a reply is
-- unicast when a route exists and broadcast otherwise (real DHCP does the same).
local function dhcp_reply(node, src, sport, port, payload)
    if node:resolve(src) then
        M.udp_send(node, src, port, sport, payload)
    else
        M.udp_send(node, M.IP_BCAST, port, sport, payload)
    end
end

local function parse_pool(spec)
    local a, b = tostring(spec or ""):match("^([%d%.]+)%s*%-%s*([%d%.]+)$")
    if not a then return nil end
    return M.ip2int(a), M.ip2int(b)
end

-- server: bind the DHCP port, allocate from the pool, commit leases
-- server-side helpers (exported so the offline tests can drive them directly)
function M.dhcp_expire(node, srv, now)
    -- recycle bound leases past their deadline and stale offers; called by the sweeper
    -- task and directly by tests
    now = now or os.clock()
    local n = 0
    for ip, le in pairs(srv.by_ip) do
        local deadline = le.expires or 0
        if deadline > 0 and now >= deadline then
            local held = now - (le.granted_at or now)
            srv.by_ip[ip] = nil
            if le.client and srv.by_client[le.client] == ip then srv.by_client[le.client] = nil end
            srv.expired = (srv.expired or 0) + 1
            n = n + 1
            node:log("DHCP_EXPIRE ip=%s client=%s state=%s held=%.1fs", M.int2ip(ip), tostring(le.client), le.state, held)
        end
    end
    return n
end

local function release_lease(node, srv, ip, why)
    local le = ip and srv.by_ip[ip]
    if not le then return false end
    srv.by_ip[ip] = nil
    if le.client and srv.by_client[le.client] == ip then srv.by_client[le.client] = nil end
    srv.freed = (srv.freed or 0) + 1
    node:log("DHCP_%s ip=%s client=%s state=%s", why, M.int2ip(ip), tostring(le.client), le.state)
    return true
end

-- conflict probe: is somebody already using this address? The hook (srv.probe_fn) makes
-- it deterministic for the offline tests; otherwise it sends an ICMP echo and waits for
-- a reply (no reply within the timeout means the address looks free).
local function probe_address(node, srv, ip, cb)
    if srv.probe_fn then
        cb(srv.probe_fn(ip) and true or false)
        return
    end
    if node.cfg.dhcp_probe == "0" then cb(false) return end
    local seq = srv.probe_seq
    srv.probe_seq = srv.probe_seq + 1
    srv.probe = { ip = ip, seq = seq, in_use = false }
    M.icmp_echo(node, ip, seq)
    local timeout = tonumber(node.cfg.dhcp_probe_timeout) or 1.5
    node:after(timeout, function()
        local p = srv.probe
        srv.probe = nil
        if p and p.seq == seq then cb(p.in_use) end
    end)
end

-- ring allocation: scan the whole pool from the last position (wrap around) so address
-- addresses recycled by the expiry sweeper come back into use
local function find_free(srv)
    local total = srv.hi - srv.lo + 1
    for k = 0, total - 1 do
        local ip = srv.lo + ((srv.next - srv.lo + k) % total)
        if not srv.by_ip[ip] and not srv.bad[ip] then
            srv.next = ip + 1
            if srv.next > srv.hi then srv.next = srv.lo end
            return ip
        end
    end
    return nil
end

-- ring allocation: scan the whole pool from the last position (wrapping around) so
-- addresses recycled by the expiry sweeper come back into use
local function find_free(srv)
    local total = srv.hi - srv.lo + 1
    for k = 0, total - 1 do
        local ip = srv.lo + ((srv.next - srv.lo + k) % total)
        if not srv.by_ip[ip] and not srv.bad[ip] then
            srv.next = ip + 1
            if srv.next > srv.hi then srv.next = srv.lo end
            return ip
        end
    end
    return nil
end

function M.dhcp_server_start(node, opts)
    opts = opts or {}
    local port = tonumber(node.cfg.dhcp_port) or DHCP_PORT
    local lo, hi = parse_pool(node.cfg.dhcp_pool)
    if not lo then
        node:log("DHCP_SERVER_NO_POOL (set dhcp_pool=start-end)")
        return nil
    end
    local gw = M.ip2int(node.cfg.dhcp_gw or (node.ifaces[1] and node.ifaces[1].cidr:match("^([%d%.]+)") or "0.0.0.0"))
    local dns = M.ip2int(node.cfg.dhcp_dns or M.int2ip(gw))
    local lease = tonumber(node.cfg.dhcp_lease) or 600
    local prefix = tonumber((node.ifaces[1] and node.ifaces[1].prefix) or 24)
    local offer_ttl = tonumber(node.cfg.dhcp_offer_ttl) or 30
    local srv = { port = port, lo = lo, hi = hi, gw = gw, dns = dns, lease = lease,
                  prefix = prefix, by_client = {}, by_ip = {}, bad = {}, next = lo,
                  leases = 0, offers = 0, naks = 0, renewals = 0, expired = 0, freed = 0,
                  offer_ttl = offer_ttl, probe_seq = 40000, probe_fn = opts.probe_fn }
    node:log("DHCP_SERVER_START pool=%s-%s gw=%s dns=%s lease=%ds port=%d probe=%s",
        M.int2ip(lo), M.int2ip(hi), M.int2ip(gw), M.int2ip(dns), lease, port,
        (srv.probe_fn and "hook") or (node.cfg.dhcp_probe == "0" and "off") or "icmp")

    -- one DISCOVER/REQUEST/RELEASE/DECLINE handler, exported for the offline tests
    local function handle(data, src, sport)
        local m = dhcp_unpack(data)
        if not m then srv.bad_packets = (srv.bad_packets or 0) + 1 return end
        -- lease identity: the client id (mac) when present, else the source address
        local key = (m.client ~= 0) and m.client or src
        if m.t == T_DISCOVER then
            local ip = srv.by_client[key]
            if ip and not srv.by_ip[ip] then ip = nil end
            local function try_ip(tries)
                if not ip then
                    ip = find_free(srv)
                    if not ip then
                        srv.naks = srv.naks + 1
                        node:log("DHCP_NAK from=%s client=%s (pool exhausted)", M.int2ip(src), tostring(key))
                        dhcp_reply(node, src, sport, port, dhcp_pack(T_NAK, m.xid, 0, 0, srv.gw, srv.dns, 0, gw, key, "pool exhausted"))
                        return
                    end
                end
                probe_address(node, srv, ip, function(in_use)
                    if in_use then
                        srv.bad[ip] = true
                        node:log("DHCP_PROBE_INUSE ip=%s (skipping)", M.int2ip(ip))
                        ip = nil
                        if tries < (srv.hi - srv.lo + 1) then return try_ip(tries + 1) end
                        srv.naks = srv.naks + 1
                        node:log("DHCP_NAK client=%s (no free address after probing)", tostring(key))
                        dhcp_reply(node, src, sport, port, dhcp_pack(T_NAK, m.xid, 0, 0, srv.gw, srv.dns, 0, gw, key, "no free address"))
                        return
                    end
                    srv.by_client[key] = ip
                    srv.by_ip[ip] = { client = key, name = (m.name ~= "" and m.name) or nil,
                                      state = "offered", granted_at = os.clock(),
                                      expires = os.clock() + srv.offer_ttl }
                    srv.offers = srv.offers + 1
                    node:log("DHCP_OFFER to=%s client=%s ip=%s name=%s", M.int2ip(src), tostring(key), M.int2ip(ip), m.name)
                    dhcp_reply(node, src, sport, port, dhcp_pack(T_OFFER, m.xid, ip, srv.prefix, srv.gw, srv.dns, srv.lease, gw, key, m.name))
                end)
            end
            try_ip(0)
        elseif m.t == T_REQUEST then
            local ip = srv.by_client[key]
            if not ip or ip ~= m.ip then
                srv.naks = srv.naks + 1
                node:log("DHCP_NAK from=%s client=%s (requested %s, ours %s)", M.int2ip(src), tostring(key),
                    M.int2ip(m.ip), ip and M.int2ip(ip) or "none")
                dhcp_reply(node, src, sport, port, dhcp_pack(T_NAK, m.xid, 0, 0, srv.gw, srv.dns, 0, gw, key, "bad request"))
                return
            end
            local le = srv.by_ip[ip]
            local renew = (le.state == "bound")
            le.state = "bound"
            le.granted_at = os.clock()
            le.expires = os.clock() + srv.lease
            if m.name ~= "" then le.name = m.name end
            srv.leases = srv.leases + 1
            if renew then srv.renewals = srv.renewals + 1 end
            node:log("DHCP_LEASE ip=%s client=%s name=%s state=bound renew=%s n=%d",
                M.int2ip(ip), tostring(key), tostring(le.name), tostring(renew), srv.leases)
            dhcp_reply(node, src, sport, port, dhcp_pack(T_ACK, m.xid, ip, srv.prefix, srv.gw, srv.dns, srv.lease, gw, key, le.name or ""))
        elseif m.t == T_RELEASE then
            release_lease(node, srv, srv.by_client[key], "RELEASE")
        elseif m.t == T_DECLINE then
            local ip = srv.by_client[key] or m.ip
            if ip and srv.by_ip[ip] then
                srv.bad[ip] = true
                release_lease(node, srv, ip, "DECLINE")
            end
        end
    end
    srv.handle = handle
    srv.sk = node:bind(port, handle)
    node.dhcp_server = srv
    node.dhcp = srv
    -- recycle expired leases (and stale offers) without waiting for new traffic
    if node.add_task then
        node:add_task("dhcp-expire", function()
            local every = tonumber(node.cfg.dhcp_sweep) or 5
            while true do
                os.sleep(every)
                M.dhcp_expire(node, srv)
            end
        end)
    end
    -- a probe reply marks the probed address as in use
    local prev_echo = node.on_echo_reply
    node.on_echo_reply = function(src, seq, rtt)
        local p = srv.probe
        if p and seq == p.seq then p.in_use = true end
        if prev_echo then prev_echo(src, seq, rtt) end
    end
    return srv
end

-- client: acquire an address, then re-address the interface and install the route.
-- Once bound it renews at T1 (lease/2 by default, dhcp_t1 overrides) so the lease does
-- not silently expire, and it can hand the lease back (dhcp_release) or report an
-- address somebody else is using (dhcp_decline).
function M.dhcp_client_start(node, iface, opts)
    opts = opts or {}
    local port = tonumber(node.cfg.dhcp_port) or DHCP_PORT
    local iface = iface or node.ifaces[1]
    if not iface then node:log("DHCP_CLIENT_NO_IFACE") return nil end
    -- os.epoch in CC only accepts "ingame"/"utc"/"local"; "utc" is milliseconds
    local xid = (os.getComputerID() * 7919 + (os.epoch and os.epoch("utc") or 0)) % 2 ^ 31
    local name = node.cfg.name or ("host" .. tostring(node.id))
    local cli = { port = port, iface = iface, xid = xid, state = "INIT", tries = 0, name = name,
                  client = node.mac or 0, server = 0, acks = 0 }
    node.dhcp_client = cli
    node:log("DHCP_CLIENT_START iface=%s placeholder=%s name=%s client=%s", iface.name, iface.cidr, name, tostring(cli.client))

    local function send(kind, ip)
        -- a client without a usable address must broadcast: no ARP and no route needed
        local m = dhcp_pack(kind, xid, ip or 0, iface.prefix, 0, 0, 0, cli.server, cli.client, name)
        M.udp_send(node, M.IP_BCAST, port, port, m, 64, iface.ip)
    end

    -- exported so the offline tests can drive the client state machine
    local function handle(data, src, sport)
        local m = dhcp_unpack(data)
        if not m or m.xid ~= xid then return end
        if m.t == T_OFFER then
            cli.offer = m
            cli.server = m.server
            node:log("DHCP_OFFER_GOT ip=%s gw=%s dns=%s from=%s", M.int2ip(m.ip), M.int2ip(m.gw), M.int2ip(m.dns), M.int2ip(src))
            send(T_REQUEST, m.ip)
        elseif m.t == T_ACK then
            cli.state = "BOUND"
            cli.bound = m
            cli.acks = cli.acks + 1
            cli.lease = m.lease
            cli.t1 = tonumber(node.cfg.dhcp_t1) or math.max(2, math.floor((m.lease or 600) * (tonumber(node.cfg.dhcp_t1_scale) or 0.5)))
            node:log("DHCP_BOUND ip=%s/%d gw=%s dns=%s lease=%ds t1=%ds client=%s",
                M.int2ip(m.ip), m.prefix, M.int2ip(m.gw), M.int2ip(m.dns), m.lease, cli.t1, tostring(cli.client))
            M.dhcp_apply(node, iface, m)
        elseif m.t == T_NAK then
            node:log("DHCP_NAK reason=%s", tostring(m.name))
            cli.state = "NAK"
        end
    end
    cli.handle = handle
    cli.sk = node:bind(port, handle)
    send(T_DISCOVER, iface.ip)          -- start() initiates immediately
    node:log("DHCP_DISCOVER from=%s", M.int2ip(iface.ip))

    node:add_task("dhcp-client", function()
        while cli.state ~= "BOUND" and cli.tries < 8 do
            os.sleep(2)
            cli.tries = cli.tries + 1
            if cli.state == "NAK" then cli.state = "INIT" end
            if cli.state ~= "BOUND" then
                node:log("DHCP_RETRY try=%d", cli.tries)
                send(T_DISCOVER, iface.ip)
            end
        end
        if cli.state ~= "BOUND" then
            node:log("DHCP_FAILED tries=%d", cli.tries)
            return
        end
        while cli.state == "BOUND" do
            os.sleep(cli.t1 or 300)
            if cli.state ~= "BOUND" then break end
            cli.renews = (cli.renews or 0) + 1
            local acks = cli.acks
            node:log("DHCP_RENEW try=%d ip=%s", cli.renews, M.int2ip(cli.bound and cli.bound.ip or 0))
            send(T_REQUEST, cli.bound and cli.bound.ip or 0)
            local waited = 0
            while cli.state == "BOUND" and cli.acks == acks and waited < 5 do
                os.sleep(0.5)
                waited = waited + 0.5
            end
            if cli.state == "BOUND" and cli.acks == acks then
                node:log("DHCP_RENEW_FAIL try=%d (no answer, rediscovering)", cli.renews)
                cli.state = "INIT"
                cli.tries = 0
                send(T_DISCOVER, iface.ip)
            end
        end
    end)
    return cli
end

-- hand the lease back to the server (apps and tests)
function M.dhcp_release(node)
    local cli = node.dhcp_client
    if not cli or cli.state ~= "BOUND" then return false end
    local ip = cli.bound and cli.bound.ip or 0
    M.udp_send(node, M.IP_BCAST, cli.port, cli.port,
        dhcp_pack(T_RELEASE, cli.xid, ip, cli.iface.prefix, 0, 0, 0, cli.server, cli.client, cli.name), 64, cli.iface.ip)
    cli.state = "RELEASED"
    node:log("DHCP_RELEASED ip=%s", M.int2ip(ip))
    return true
end

-- report an address we found in use by somebody else (server blacklists it)
function M.dhcp_decline(node, ip)
    local cli = node.dhcp_client
    if not cli then return false end
    local addr = ip or (cli.bound and cli.bound.ip) or 0
    M.udp_send(node, M.IP_BCAST, cli.port, cli.port,
        dhcp_pack(T_DECLINE, cli.xid, addr, cli.iface.prefix, 0, 0, 0, cli.server, cli.client, cli.name), 64, cli.iface.ip)
    cli.state = "DECLINED"
    node:log("DHCP_DECLINED ip=%s", M.int2ip(addr))
    return true
end

-- adopt a lease: re-address the interface, replace its connected route, set the gw
function M.dhcp_apply(node, iface, m)
    local old_net = iface.net
    iface.ip, iface.prefix = m.ip, m.prefix
    iface.cidr = M.int2ip(m.ip) .. "/" .. m.prefix
    iface.net = M.masked(iface.ip, iface.prefix)
    local keep = {}
    for _, r in ipairs(node.routes.entries) do
        local is_connected_here = (r.kind == "connected" and r.iface == iface and r.net == old_net)
        if not is_connected_here then keep[#keep + 1] = r end
    end
    node.routes.entries = keep
    M.route_connected(node.routes, iface)
    if m.gw and m.gw ~= 0 then M.route_default(node.routes, m.gw) end
    node:log("DHCP_APPLIED iface=%s addr=%s net=%s gw=%s", iface.name, iface.cidr, M.int2ip(iface.net), M.int2ip(m.gw or 0))
    if node.dns_register then node:dns_register(node.cfg.name or m.name) end
    return true
end

-- ===== lookup-lite ==========================================================
local function dns_pack(t, name, ip)
    name = name or ""
    return u8(t) .. u8(#name) .. name .. u32(ip or 0)
end

local function dns_unpack(s)
    if #s < 2 then return nil end
    local nl = byte(s, 2)
    if #s < 2 + nl + 4 then return nil end
    return { t = byte(s, 1), name = sub(s, 3, 2 + nl), ip = r32(s, 3 + nl) }
end

function M.dns_server_start(node, opts)
    opts = opts or {}
    local port = tonumber(node.cfg.dns_port) or DNS_PORT
    local srv = { port = port, names = {}, queries = 0, registrations = 0 }
    -- leases published by our own DHCP server are resolvable too
    node:log("DNS_SERVER_START port=%d", port)
    srv.sk = node:bind(port, function(data, src, sport)
        local m = dns_unpack(data)
        if not m or m.name == "" then return end
        if m.t == D_REGISTER then
            srv.names[m.name] = m.ip
            srv.registrations = srv.registrations + 1
            node:log("DNS_REG name=%s ip=%s from=%s", m.name, M.int2ip(m.ip), M.int2ip(src))
        elseif m.t == D_QUERY then
            srv.queries = srv.queries + 1
            local ip = srv.names[m.name]
            -- fall back to the DHCP lease table (name -> address)
            if not ip and node.dhcp then
                for leaseIp, le in pairs(node.dhcp.by_ip) do
                    if le.name == m.name then ip = leaseIp break end
                end
            end
            node:log("DNS_QUERY name=%s answer=%s from=%s", m.name, ip and M.int2ip(ip) or "none", M.int2ip(src))
            M.udp_send(node, src, port, sport, dns_pack(ip and D_ANSWER or D_NACK, m.name, ip or 0))
        end
    end)
    node.dns = srv
    return srv
end

function M.hosts_load(node, path)
    path = path or "hosts.txt"
    local t = {}
    if fs.exists(path) then
        local f = fs.open(path, "r")
        for line in f.readLine do
            line = line:gsub("#.*$", ""):gsub("^%s+", ""):gsub("%s+$", "")
            local name, ip = line:match("^([%w%-_.]+)%s+([%d%.]+)$")
            if name then t[name] = M.ip2int(ip) end
        end
        f.close()
        local n = 0
        for _ in pairs(t) do n = n + 1 end
        if n > 0 then node:log("HOSTS_LOADED n=%d path=%s", n, path) end
    end
    node.hosts = t
    return t
end

-- advertise our name/address to the name server
function M.dns_register(node, name)
    name = name or node.cfg.name
    if not name or name == "" then return false end
    local srv = node.cfg.dns_server and M.ip2int(node.cfg.dns_server)
        or (node.cfg.gw and M.ip2int(node.cfg.gw))
    if not srv then node:log("DNS_REGISTER_NO_SERVER"); return false end
    local ip = node:pick_src(srv)
    if not ip or ip == 0 then ip = node.ifaces[1] and node.ifaces[1].ip or 0 end
    local port = tonumber(node.cfg.dns_port) or DNS_PORT
    M.udp_send(node, srv, port, port, dns_pack(D_REGISTER, name, ip))
    node:log("DNS_REGISTER_SENT name=%s ip=%s to=%s", name, M.int2ip(ip), M.int2ip(srv))
    if node.hosts then node.hosts[name] = ip end
    return true
end

-- name -> ip. Blocking-style: call inside a task (uses os.sleep), or pass a
-- callback for the non-blocking form.
function M.lookup(node, name, timeout, cb)
    local t = node.hosts or {}
    if t[name] then
        if cb then cb(t[name]) end
        return t[name]
    end
    local srv = node.cfg.dns_server and M.ip2int(node.cfg.dns_server)
        or (node.cfg.gw and M.ip2int(node.cfg.gw))
    if not srv then
        node:log("LOOKUP_NO_SERVER name=%s", name)
        if cb then cb(nil) end
        return nil
    end
    local port = tonumber(node.cfg.dns_port) or DNS_PORT
    node:log("LOOKUP_QUERY name=%s via=%s", name, M.int2ip(srv))
    local result = nil
    local sk = node:bind(port, function(data, src, sport)
        local m = dns_unpack(data)
        if not m or m.name ~= name then return end
        if m.t == D_ANSWER and m.ip ~= 0 then
            result = m.ip
            node.hosts[name] = m.ip
        else
            result = false
        end
    end)
    M.udp_send(node, srv, port, port, dns_pack(D_QUERY, name))
    local waited = 0
    while result == nil and waited < (timeout or 3) do
        os.sleep(0.25)
        waited = waited + 0.25
    end
    if sk and sk.close then pcall(function() sk:close() end) end
    if result then
        node:log("LOOKUP_ANSWER name=%s ip=%s after=%.2fs", name, M.int2ip(result), waited)
        if cb then cb(result) end
        return result
    end
    node:log("LOOKUP_TIMEOUT name=%s after=%.2fs", name, waited)
    if cb then cb(nil) end
    return nil
end

-- ===== setup hook ===========================================================
-- Called from node:setup(); wired entirely from configuration keys.
function M.services_setup(node)
    M.hosts_load(node, node.cfg.hosts_file or "hosts.txt")
    if node.cfg.dhcp == "1" then
        local iface = node.ifaces[1]
        for _, i in ipairs(node.ifaces) do
            if not i.is_wan then iface = i break end
        end
        M.dhcp_client_start(node, iface)
    end
    if node.cfg.dhcp_pool then M.dhcp_server_start(node) end
    if node.cfg.dns == "1" then M.dns_server_start(node) end
    if node.cfg.name and node.cfg.name ~= "" and node.cfg.dhcp ~= "1" then
        node:after(1.0, function() M.dns_register(node) end)
    end
end

return M
]==],
    dv = [==[
--[[- rpv/dv.lua ? distance-vector routing (RIP-lite) with loop suppression.

Lets a set of routers build their forwarding tables by themselves instead of
being hand-configured with routes.txt. Everything rides on rpv UDP, so it works
on wired, wireless and cross-dimension links.

How it works
  * every router periodically broadcasts an ANNOUNCE on each non-WAN interface:
    the list of (net, prefix, metric) it can reach -- its own connected subnets
    with metric 0, everything else with the metric it learned, +1 per hop
  * a node that hears an ANNOUNCE on interface I from neighbour N installs
    `net -> via N` on I with metric = announced + 1, and updates the real route
    table (kind "dv"; route.lua ranks it below connected/static routes)
  * metric 16 means unreachable ("infinity", RIP's 16)

Loop suppression
  * **split horizon with poisoned reverse**: to the neighbour a route was learned
    from, that route is announced back with metric = infinity, so two routers can
    never point at each other
  * **hop limit**: anything at 16 is not installed and removes the route that
    came in over that interface
  * **expiry (hold-down)**: a route not refreshed within `dv_timeout` seconds is
    removed (DV_EXPIRE) instead of lingering

Config keys (node):
    dv=1                 enable
    dv_port=6800         UDP port (all routers must match)
    dv_interval=3        announce period in seconds
    dv_jitter=0          randomise the period by +/- this fraction (0..1); use it on
                         large networks so announces do not arrive in lockstep
    dv_timeout=12        route lifetime without a refresh

Logs: DV_ANNOUNCE, DV_INSTALL, DV_UPDATE, DV_REMOVE, DV_EXPIRE, DV_ROUTE (one
line per installed route, emitted every interval for the harness), DV_STATE.
]]
local M = ...
local u8, u16, u32, r16, r32, byte, sub = M.u8, M.u16, M.u32, M.r16, M.r32, M.byte, M.sub

local PORT = 6800
local T_ANNOUNCE = 1
local INF = 16                 -- hop count meaning "unreachable"

local function dv_pack(entries)
    local out = { u8(T_ANNOUNCE), u16(#entries) }
    for _, e in ipairs(entries) do
        out[#out + 1] = u32(e.net) .. u8(e.prefix) .. u8(e.metric)
    end
    return table.concat(out)
end

local function dv_unpack(s)
    -- u8 type | u16 count | count * (u32 net | u8 prefix | u8 metric)
    if #s < 3 then return nil end
    local n = r16(s, 2)
    if #s < 3 + n * 6 then return nil end
    local out = {}
    for i = 0, n - 1 do
        local o = 4 + i * 6          -- entries start after type(1) + count(2)
        out[#out + 1] = { net = r32(s, o), prefix = byte(s, o + 4), metric = byte(s, o + 5) }
    end
    return out
end

function M.dv_new(node, opts)
    opts = opts or {}
    return {
        node = node,
        port = tonumber(node.cfg.dv_port) or PORT,
        interval = tonumber(node.cfg.dv_interval) or 3,
        timeout = tonumber(node.cfg.dv_timeout) or 12,
        routes = {},          -- net -> { prefix, metric, iface, gw, via, age, own }
        neighbors = {},       -- iface name -> last announce time
        installs = 0, updates = 0, removes = 0, expires = 0, poisoned = 0, announces = 0,
    }
end

-- our own subnets, metric 0, never expired
local function seed_own(dv)
    local node = dv.node
    for _, iface in ipairs(node.ifaces) do
        if not iface.is_wan then
            local key = iface.net .. "/" .. iface.prefix
            dv.routes[key] = { prefix = iface.prefix, net = iface.net, metric = 0,
                               iface = iface, via = nil, own = true, age = 0 }
        end
    end
end

function M.dv_setup(node, opts)
    local dv = M.dv_new(node, opts)
    node.dv = dv
    seed_own(dv)
    node:log("DV_START port=%d interval=%ds timeout=%ds own_subnets=%d",
        dv.port, dv.interval, dv.timeout, (function() local n = 0 for _ in pairs(dv.routes) do n = n + 1 end return n end)())

    dv.sk = node:bind(dv.port, function(data, src, sport)
        local entries = dv_unpack(data)
        if not entries then return end
        local iface = nil
        -- which of our interfaces is this neighbour on?
        for _, i in ipairs(node.ifaces) do
            if not i.is_wan and M.masked(src, i.prefix) == i.net then iface = i break end
        end
        if not iface then
            node:log("DV_IGNORE from=%s (not on a local subnet)", M.int2ip(src))
            return
        end
        dv.neighbors[iface.name] = os.clock()
        if node.cfg.dv_debug == "1" then
            node:log("DV_RX from=%s on=%s entries=%d", M.int2ip(src), iface.name, #entries)
        end
        for _, e in ipairs(entries) do
            if node.cfg.dv_debug == "1" then
                node:log("DV_RX_ENTRY net=%s/%d metric=%d", M.int2ip(e.net), e.prefix, e.metric)
            end
            local key = e.net .. "/" .. e.prefix
            local have = dv.routes[key]
            if e.metric >= INF then
                -- poisoned reverse: a neighbour says "do not come this way".
                -- Only the neighbour we actually route through may invalidate our route:
                -- on a shared segment (a grid LAN has several routers) another neighbour
                -- poisons the route it learned FROM us, and treating that as authoritative
                -- made 3+ hop routes flap install/remove forever.
                if have and not have.own and have.gw == src then
                    dv.routes[key] = nil
                    M.route_upsert(node.routes, have.prefix, have.net, have.iface, nil, "dv", true)
                    dv.removes = dv.removes + 1
                    node:log("DV_REMOVE net=%s/%d reason=poisoned via=%s gw=%s", M.int2ip(e.net), e.prefix, iface.name, M.int2ip(src))
                elseif have and not have.own and have.via == iface.name then
                    dv.poison_ignored = (dv.poison_ignored or 0) + 1
                    if node.cfg.dv_debug == "1" then
                        node:log("DV_POISON_IGNORED net=%s/%d from=%s (our gw is %s)",
                            M.int2ip(e.net), e.prefix, M.int2ip(src), M.int2ip(have.gw or 0))
                    end
                end
                dv.poisoned = dv.poisoned + 1
            else
                -- never take our own connected subnet from someone else
                local is_own = false
                for _, i in ipairs(node.ifaces) do
                    if not i.is_wan and i.net == e.net and i.prefix == e.prefix then is_own = true end
                end
                if not is_own then
                    local candidate = e.metric + 1
                    if candidate < INF and (not have or candidate < have.metric or have.gw == src) then
                        -- a hand-configured/connected route of the same prefix always
                        -- wins: don't shadow it (route_lookup keeps first-added order,
                        -- so the priority is enforced here at install time)
                        local best = M.route_lookup(node.routes, e.net)
                        local blocked = best and best.net == e.net and best.prefix == e.prefix
                            and (M.ROUTE_RANK[best.kind] or 2) > (M.ROUTE_RANK.dv or 2)
                        if blocked then
                            node:log("DV_SHADOWED net=%s/%d by=%s", M.int2ip(e.net), e.prefix, tostring(best.kind))
                        else
                            local isNew = (not have) or have.own
                            dv.routes[key] = { prefix = e.prefix, net = e.net, metric = candidate,
                                               iface = iface, gw = src, via = iface.name, age = 0 }
                            M.route_upsert(node.routes, e.prefix, e.net, iface, src, "dv")
                            if isNew then
                                dv.installs = dv.installs + 1
                                node:log("DV_INSTALL net=%s/%d metric=%d gw=%s via=%s", M.int2ip(e.net), e.prefix, candidate, M.int2ip(src), iface.name)
                            else
                                dv.updates = dv.updates + 1
                                node:log("DV_UPDATE net=%s/%d metric=%d gw=%s via=%s", M.int2ip(e.net), e.prefix, candidate, M.int2ip(src), iface.name)
                            end
                        end
                    end
                end
            end
        end
        dv.dirty = true
    end)

    node:add_task("dv", function()
        -- dv_jitter (0..1, default 0): randomise each period by +/- jitter so a large
        -- network does not announce in lockstep. With dozens of routers on shared media
        -- the synchronised bursts starve ARP and neighbour discovery (measured: a 6x6
        -- grid dropped to 10% delivery without it). Kept at 0 by default so the small
        -- deterministic test topologies stay reproducible.
        local jitter = tonumber(node.cfg.dv_jitter) or 0
        local function period()
            if jitter <= 0 then return dv.interval end
            local f = 1 + (math.random() * 2 - 1) * jitter
            if f < 0.25 then f = 0.25 end
            return dv.interval * f
        end
        os.sleep(1)                        -- let the interfaces settle
        while true do
            local now = os.clock()
            -- 1. announce on every non-WAN interface (split horizon + poisoned reverse)
            for _, iface in ipairs(node.ifaces) do
                if not iface.is_wan then
                    local entries = {}
                    for _, r in pairs(dv.routes) do
                        local metric = r.metric
                        if not r.own and r.via == iface.name then metric = INF end   -- poison reverse
                        entries[#entries + 1] = { net = r.net, prefix = r.prefix, metric = metric }
                    end
                    if node.cfg.dv_debug == "1" then
                        for _, e in ipairs(entries) do
                            node:log("DV_TX iface=%s net=%s/%d metric=%d", iface.name, M.int2ip(e.net), e.prefix, e.metric)
                        end
                    end
                    M.udp_send(node, M.IP_BCAST, dv.port, dv.port, dv_pack(entries), 1, iface.ip)
                    dv.announces = dv.announces + 1
                end
            end
            -- 2. age / expire learned routes
            for key, r in pairs(dv.routes) do
                if not r.own then
                    r.age = (r.age or 0) + dv.interval
                    if r.age > dv.timeout then
                        dv.routes[key] = nil
                        M.route_upsert(node.routes, r.prefix, r.net, r.iface, nil, "dv", true)
                        dv.expires = dv.expires + 1
                        node:log("DV_EXPIRE net=%s/%d via=%s after=%ds", M.int2ip(r.net), r.prefix, tostring(r.via), r.age)
                    end
                end
            end
            -- 3. report (the harness asserts on these lines)
            for _, r in pairs(dv.routes) do
                if not r.own then
                    node:log("DV_ROUTE net=%s/%d metric=%d gw=%s via=%s age=%d",
                        M.int2ip(r.net), r.prefix, r.metric, r.gw and M.int2ip(r.gw) or "-", tostring(r.via), r.age or 0)
                end
            end
            local nRoutes, nNb = 0, 0
            for _, r in pairs(dv.routes) do if not r.own then nRoutes = nRoutes + 1 end end
            for _, t in pairs(dv.neighbors) do if now - t <= dv.timeout then nNb = nNb + 1 end end
            node:log("DV_STATE learned=%d neighbors=%d installs=%d updates=%d removes=%d expires=%d poisoned=%d announces=%d",
                nRoutes, nNb, dv.installs, dv.updates, dv.removes, dv.expires, dv.poisoned, dv.announces)
            os.sleep(period())
        end
    end)
    return dv
end

M.DV_INFINITY = INF

return M
]==],
    nat = [==[
--[[- rpv/nat.lua ? NAT-lite: port forwarding (DNAT) and masquerade (PAT).

Why this exists here: the roadmap's "do not do" note rejects *internet* NAT (CC has no
public network). What is useful in a CC world is the other half of the job: letting a
whole private subnet share ONE external identity, and letting a single well-known port
on the router reach one internal computer. That is exactly what this module does, with
no assumptions about a real internet.

Configuration (node keys):
    nat=1                                   enable
    nat_out=<iface name>                    the "external" interface (default: last iface)
    nat_forward=7000>10.0.1.2:7000,...      DNAT rules (udp by default, `tcp:` ignored)
    nat_port_base=40000                     start of the translated port pool
    nat_max_flows=64
    nat_timeout=60                          seconds an idle flow is kept

Behaviour
  * outbound (private host -> external): the source address/port is rewritten to the
    external address plus a port from the pool, and a flow entry records how to map the
    reply back. UDP gets its checksum recomputed; ICMP echo requests are translated by
    id so replies match.
  * inbound to a forwarded port: the destination is rewritten to the internal host and
    the flow is created so its replies come back out.
  * inbound to the external address with no rule and no matching flow: logged as
    NAT_DROP (and an ICMP port-unreachable is *not* generated, matching a dark NAT).
  * flows expire (NAT_EXPIRE) and the pool is bounded (NAT_POOL_EXHAUSTED).

Logs: NAT_START, NAT_XLATE, NAT_FWD, NAT_DROP, NAT_EXPIRE, NAT_STATE.
]]
local M = ...
local u8, u16, u32, r16, r32, byte, sub, cksum, int2ip = M.u8, M.u16, M.u32, M.r16, M.r32, M.byte, M.sub, M.cksum, M.int2ip

local T_OUT = 1
local T_IN = 2

local function proto_name(p) return (p == M.IP_UDP) and "udp" or (p == M.IP_ICMP) and "icmp" or tostring(p) end

-- rebuild a UDP datagram with a checksum valid for the new src/dst
local function udp_rechecksum(payload, src, dst)
    if #payload < 8 then return payload end
    local len = r16(payload, 5)
    local data = sub(payload, 9, len)
    local pseudo = u32(src) .. u32(dst) .. u8(0) .. u8(M.IP_UDP) .. u16(len)
    local ck = cksum(pseudo .. sub(payload, 1, 6) .. u16(0) .. data)
    if ck == 0 then ck = 0xFFFF end
    return sub(payload, 1, 6) .. u16(ck) .. data
end

-- ICMP echo request/reply: type(1) code(1) cksum(2) id(2) seq(2) data
local function icmp_rechecksum(payload)
    if #payload < 4 then return payload end
    local ck = cksum(sub(payload, 1, 2) .. u16(0) .. sub(payload, 5))
    return sub(payload, 1, 2) .. u16(ck) .. sub(payload, 5)
end

local function parse_rules(spec)
    local out = {}
    for rule in tostring(spec or ""):gmatch("[^,]+") do
        local port, host, hport = rule:match("^%s*(%d+)%s*>%s*([%d%.]+):(%d+)%s*$")
        if port then out[tonumber(port)] = { ip = M.ip2int(host), port = tonumber(hport) } end
    end
    return out
end

function M.nat_new(node, opts)
    opts = opts or {}
    local out_iface = nil
    local want = node.cfg.nat_out
    for _, i in ipairs(node.ifaces) do
        if want and i.name == want then out_iface = i end
    end
    if not out_iface then
        for _, i in ipairs(node.ifaces) do if not i.is_wan and not i.is_fabric then out_iface = i end end
    end
    return {
        node = node,
        out = out_iface,
        ext_ip = out_iface and out_iface.ip or 0,
        rules = parse_rules(node.cfg.nat_forward),
        port_base = tonumber(node.cfg.nat_port_base) or 40000,
        next_port = tonumber(node.cfg.nat_port_base) or 40000,
        max_flows = tonumber(node.cfg.nat_max_flows) or 64,
        timeout = tonumber(node.cfg.nat_timeout) or 60,
        flows = {},                 -- key -> flow
        by_ext = {},                -- "proto:port" -> key
        xlate = 0, fwd_hits = 0, drops = 0, expires = 0, exhausted = 0, icmp = 0,
    }
end

function M.nat_setup(node, opts)
    if not node.cfg.nat or node.cfg.nat ~= "1" then return nil end
    local nat = M.nat_new(node, opts)
    if not nat.out then
        node:log("NAT_NO_EXTERNAL_IFACE")
        return nil
    end
    node.nat = nat
    local n = 0
    for _ in pairs(nat.rules) do n = n + 1 end
    node:log("NAT_START external=%s addr=%s rules=%d port_base=%d max_flows=%d timeout=%ds",
        nat.out.name, int2ip(nat.ext_ip), n, nat.port_base, nat.max_flows, nat.timeout)

    -- flow expiry + periodic report for the harness
    node:add_task("nat", function()
        local nextReport = os.clock()
        while true do
            os.sleep(1)
            local now = os.clock()
            for k, f in pairs(nat.flows) do
                if f.expires <= now then
                    nat.flows[k] = nil
                    nat.by_ext[f.proto .. ":" .. f.ext_port] = nil
                    nat.expires = nat.expires + 1
                end
            end
            if now >= nextReport then
                nextReport = now + 5
                node:log("NAT_STATE flows=%d xlate=%d fwd=%d drops=%d expires=%d exhausted=%d icmp=%d",
                    (function() local c = 0 for _ in pairs(nat.flows) do c = c + 1 end return c end)(),
                    nat.xlate, nat.fwd_hits, nat.drops, nat.expires, nat.exhausted, nat.icmp)
            end
        end
    end)
    return nat
end

local function alloc_port(nat)
    for _ = 1, 4096 do
        local p = nat.next_port
        nat.next_port = nat.next_port + 1
        if nat.next_port > 60000 then nat.next_port = nat.port_base end
        if not nat.by_ext["17:" .. p] and not nat.by_ext["1:" .. p] then return p end
    end
    return nil
end

-- returns: action, new_src, new_dst, new_payload
--   "forward" = send the (translated) packet onward, "drop" = discard, nil = untouched
function M.nat_input_hook(node, iface, h, payload)
    local nat = node.nat
    if not nat then return nil end
    local now = os.clock()

    -- 1. traffic arriving on the external interface towards our external address
    if iface == nat.out and h.dst == nat.ext_ip then
        if h.proto == M.IP_UDP and #payload >= 8 then
            local dport = r16(payload, 3)
            local sport = r16(payload, 1)
            -- reply for an existing flow?
            local key = nat.by_ext["17:" .. dport]
            local f = key and nat.flows[key]
            if f and f.proto == M.IP_UDP then
                f.expires = now + nat.timeout
                -- reply: keep the peer's source port, retarget the destination to the
                -- internal host and its original port
                local np = u16(sport) .. u16(f.int_port) .. sub(payload, 5)
                np = udp_rechecksum(np, h.src, f.int_ip)
                return "forward", h.src, f.int_ip, np
            end
            -- static port forward?
            local r = nat.rules[dport]
            if r then
                nat.fwd_hits = nat.fwd_hits + 1
                -- remember the mapping so the reply leaves with the SAME external port
                local fkey = "fwd:" .. dport .. ":" .. h.src .. ":" .. sport
                nat.flows[fkey] = { proto = M.IP_UDP, int_ip = r.ip, int_port = r.port, ext_port = dport,
                                    peer = h.src, peer_port = sport, expires = now + nat.timeout, key = fkey }
                nat.by_ext["17:" .. dport] = fkey
                local np = udp_rechecksum(u16(sport) .. u16(r.port) .. sub(payload, 5), h.src, r.ip)
                node:log("NAT_FWD proto=udp ext_port=%d -> %s:%d from=%s sport=%d", dport, int2ip(r.ip), r.port, int2ip(h.src), sport)
                return "forward", h.src, r.ip, np
            end
            nat.drops = nat.drops + 1
            node:log("NAT_DROP proto=udp dst=%s port=%d from=%s (no rule, no flow)", int2ip(h.dst), dport, int2ip(h.src))
            return "drop"
        elseif h.proto == M.IP_ICMP and #payload >= 8 and byte(payload, 1) == 0 then
            -- echo reply for a masqueraded request: match on the translated id
            local id = r16(payload, 5)
            local ikey = nat.by_ext["1:" .. id]
            local f = ikey and nat.flows[ikey]
            if f then
                f.expires = now + nat.timeout
                local np = sub(payload, 1, 4) .. u16(f.int_id) .. sub(payload, 7)
                np = icmp_rechecksum(np)
                nat.icmp = nat.icmp + 1
                return "forward", h.src, f.int_ip, np
            end
            nat.drops = nat.drops + 1
            node:log("NAT_DROP proto=icmp dst=%s id=%d from=%s (no flow)", int2ip(h.dst), id, int2ip(h.src))
            return "drop"
        end
        return nil
    end

    -- 2. outbound: a private host sending through us (arrives on another interface)
    if iface ~= nat.out and not iface.is_wan and not iface.is_fabric then
        local isExternalDst = false
        local p = node:resolve(h.dst)
        if p and p.iface == nat.out then isExternalDst = true end
        if not isExternalDst then return nil end

        if h.proto == M.IP_UDP and #payload >= 8 then
            local sport, dport = r16(payload, 1), r16(payload, 3)
            local key = "udp:" .. h.src .. ":" .. sport .. ":" .. h.dst .. ":" .. dport
            local f = nat.flows[key]
            if not f then
                local n = 0
                for _ in pairs(nat.flows) do n = n + 1 end
                if n >= nat.max_flows then
                    nat.exhausted = nat.exhausted + 1
                    node:log("NAT_POOL_EXHAUSTED flows=%d (dropping %s:%d)", n, int2ip(h.src), sport)
                    return "drop"
                end
                local ext_port = alloc_port(nat)
                if not ext_port then
                    nat.exhausted = nat.exhausted + 1
                    return "drop"
                end
                f = { proto = M.IP_UDP, int_ip = h.src, int_port = sport, ext_port = ext_port,
                      peer = h.dst, peer_port = dport, expires = now + nat.timeout, key = key }
                nat.flows[key] = f
                nat.by_ext["17:" .. ext_port] = key
            else
                f.expires = now + nat.timeout
            end
            nat.xlate = nat.xlate + 1
            local np = udp_rechecksum(u16(f.ext_port) .. sub(payload, 3), nat.ext_ip, h.dst)
            node:log("NAT_XLATE proto=udp %s:%d -> %s:%d dst=%s:%d flows=%d",
                int2ip(h.src), sport, int2ip(nat.ext_ip), f.ext_port, int2ip(h.dst), dport, (function() local c = 0 for _ in pairs(nat.flows) do c = c + 1 end return c end)())
            return "rewrite", nat.ext_ip, h.dst, np
        elseif h.proto == M.IP_ICMP and #payload >= 8 and byte(payload, 1) == 8 then
            local id = r16(payload, 5)
            local key = "icmp:" .. h.src .. ":" .. id
            if not nat.flows[key] then
                local ext_id = alloc_port(nat) or id
                nat.flows[key] = { proto = M.IP_ICMP, int_ip = h.src, int_id = id, ext_id = ext_id,
                                   peer = h.dst, expires = now + nat.timeout, key = key }
                nat.by_ext["1:" .. ext_id] = key     -- reverse lookup for the echo reply
            end
            local f = nat.flows[key]
            f.expires = now + nat.timeout
            nat.xlate = nat.xlate + 1
            local np = sub(payload, 1, 4) .. u16(f.ext_id) .. sub(payload, 7)
            np = icmp_rechecksum(np)
            node:log("NAT_XLATE proto=icmp %s id=%d -> %s id=%d dst=%s", int2ip(h.src), id, int2ip(nat.ext_ip), f.ext_id, int2ip(h.dst))
            return "rewrite", nat.ext_ip, h.dst, np
        end
        return nil
    end
    return nil
end

return M
]==],
    mcast = [==[
--[[- rpv/mcast.lua ? multicast groups and broadcast/multicast domain control.

CC networks are small and flat, so "multicast" here is deliberately simple: a
multicast packet is an IP datagram to an address in 224.0.0.0/4 sent as an L2
broadcast on the local segment, and every receiver keeps only the groups it joined.
Routers decide, per group, which segments may exchange group traffic
(`mcast_domains=LAN-A>LAN-B,LAN-B>LAN-A`), with a per-group rate limit so one noisy
sender cannot flood a bridged domain.

Because limited broadcast (255.255.255.255) is *not* forwarded by the IP layer by
default, the same domain machinery can optionally relay it (`bcast_relay=LAN-A>LAN-B`)
and rate-limit it -- that is the "broadcast domain control" half.

Configuration (node keys):
    mcast=1                          enable the group/domain machinery on a router
    mcast_groups=239.1.1.1,...       groups this node joins (host side)
    mcast_domains=LAN-A>LAN-B,...    allowed ingress>egress pairs for group traffic
    mcast_rate=20                    max group packets per second per (group, ingress)
    bcast_relay=LAN-A>LAN-B,...      also relay limited broadcast across these pairs
    bcast_rate=10                    rate limit for relayed broadcasts

API: rpv.mcast_setup(node), rpv.mcast_join(node, group), rpv.mcast_leave(node, group),
     rpv.mcast_send(node, group, dport, data), rpv.mcast_joined(node, group),
     rpv.mcast_test(ip), rpv.mcast_input_hook(node, iface, h, payload)

Logs: MCAST_START, MCAST_JOIN, MCAST_SEND, MCAST_FORWARD, MCAST_LOCAL, MCAST_DENY,
MCAST_RATE_DROP, BCAST_FORWARD, BCAST_RATE_DROP, MCAST_STATE.
]]
local M = ...
local u8, u16, u32, r16, byte, sub = M.u8, M.u16, M.u32, M.r16, M.byte, M.sub

local function parse_pairs(spec)
    local out = {}
    for pair in tostring(spec or ""):gmatch("[^,]+") do
        local a, b = pair:match("^%s*([%w%-_]+)%s*>%s*([%w%-_]+)%s*$")
        if a then out[a .. ">" .. b] = true end
    end
    return out
end

function M.mcast_test(ip)
    return ip >= M.ip2int("224.0.0.0") and ip <= M.ip2int("239.255.255.255")
end

function M.mcast_new(node, opts)
    local groups = {}
    for g in tostring(node.cfg.mcast_groups or ""):gmatch("[^,]+") do
        local s = g:match("^%s*([%d%.]+)%s*$")
        if s and M.mcast_test(M.ip2int(s)) then groups[M.ip2int(s)] = true end
    end
    return {
        node = node,
        groups = groups,
        domains = parse_pairs(node.cfg.mcast_domains),
        bcast = parse_pairs(node.cfg.bcast_relay),
        rate = tonumber(node.cfg.mcast_rate) or 20,
        bcast_rate = tonumber(node.cfg.bcast_rate) or 10,
        buckets = {},                -- key -> {n, t0}
        sent = 0, local_deliver = 0, forwarded = 0, denied = 0, rate_drops = 0,
        bcast_forwarded = 0, bcast_drops = 0,
    }
end

function M.mcast_setup(node, opts)
    if node.cfg.mcast ~= "1" and not node.cfg.mcast_groups then return nil end
    local mc = M.mcast_new(node, opts)
    node.mcast = mc
    local ng, nd = 0, 0
    for _ in pairs(mc.groups) do ng = ng + 1 end
    for _ in pairs(mc.domains) do nd = nd + 1 end
    node:log("MCAST_START groups=%d domains=%d rate=%d/s bcast_relay=%d", ng, nd, mc.rate,
        (function() local c = 0 for _ in pairs(mc.bcast) do c = c + 1 end return c end)())
    node:add_task("mcast", function()
        while true do
            os.sleep(5)
            node:log("MCAST_STATE joined=%d sent=%d local=%d forwarded=%d denied=%d rate_drops=%d bcast_fwd=%d bcast_drops=%d",
                (function() local c = 0 for _ in pairs(mc.groups) do c = c + 1 end return c end)(),
                mc.sent, mc.local_deliver, mc.forwarded, mc.denied, mc.rate_drops, mc.bcast_forwarded, mc.bcast_drops)
        end
    end)
    return mc
end

function M.mcast_join(node, group)
    if not node.mcast then return false end
    local ip = type(group) == "number" and group or M.ip2int(group)
    if not M.mcast_test(ip) then return false end
    node.mcast.groups[ip] = true
    node:log("MCAST_JOIN group=%s", M.int2ip(ip))
    return true
end

function M.mcast_leave(node, group)
    if not node.mcast then return false end
    node.mcast.groups[type(group) == "number" and group or M.ip2int(group)] = nil
    return true
end

function M.mcast_joined(node, group)
    if not node.mcast then return false end
    return node.mcast.groups[type(group) == "number" and group or M.ip2int(group)] == true
end

-- send to a group: L2 broadcast on the segment the iface is on
function M.mcast_send(node, group, dport, data, sport, iface)
    local ip = type(group) == "number" and group or M.ip2int(group)
    if not M.mcast_test(ip) then return false end
    sport = sport or dport
    if node.udp then node.udp.tx = node.udp.tx + 1 end
    local len = 8 + #data
    local src = (iface and iface.ip) or (node.ifaces[1] and node.ifaces[1].ip) or 0
    local pseudo = u32(src) .. u32(ip) .. u8(0) .. u8(M.IP_UDP) .. u16(len)
    local ck = M.cksum(pseudo .. u16(sport) .. u16(dport) .. u16(len) .. u16(0) .. data)
    if ck == 0 then ck = 0xFFFF end
    local pkt = u16(sport) .. u16(dport) .. u16(len) .. u16(ck) .. data
    if node.mcast then node.mcast.sent = node.mcast.sent + 1 end
    node:log("MCAST_SEND group=%s dport=%d bytes=%d", M.int2ip(ip), dport, #data)
    return node:send_ip(ip, M.IP_UDP, pkt, 1, src)
end

local function bucket_ok(mc, key, limit, now)
    local b = mc.buckets[key]
    if not b or now - b.t0 >= 1 then
        mc.buckets[key] = { n = 1, t0 = now }
        return true
    end
    b.n = b.n + 1
    return b.n <= limit
end

-- hook from ip_deliver: decides delivery/forwarding for group and (optionally)
-- limited-broadcast traffic. Returns "local" (deliver here), "forward" with an
-- egress iface list, or "drop".
function M.mcast_input_hook(node, iface, h, payload)
    local mc = node.mcast
    if not mc then return nil end
    local now = os.clock()

    if h.dst == M.IP_BCAST then
        -- broadcast domain control: relay only across allowed ingress>egress pairs
        local egress = {}
        for pair in pairs(mc.bcast) do
            local a, b = pair:match("^([^>]+)>(.+)$")
            if a == iface.name then egress[#egress + 1] = b end
        end
        if #egress == 0 then return nil end
        if not bucket_ok(mc, "bcast:" .. iface.name, mc.bcast_rate, now) then
            mc.bcast_drops = mc.bcast_drops + 1
            node:log("BCAST_RATE_DROP from=%s on=%s limit=%d/s", M.int2ip(h.src), iface.name, mc.bcast_rate)
            return "drop"
        end
        mc.bcast_forwarded = mc.bcast_forwarded + 1
        node:log("BCAST_FORWARD src=%s on=%s -> %s", M.int2ip(h.src), iface.name, table.concat(egress, ","))
        return "forward", egress
    end

    if not M.mcast_test(h.dst) then return nil end
    -- is this group ours? deliver locally (only joined sockets will accept it)
    if mc.groups[h.dst] then
        mc.local_deliver = mc.local_deliver + 1
        node:log("MCAST_LOCAL group=%s from=%s on=%s", M.int2ip(h.dst), M.int2ip(h.src), iface.name)
        return "local"
    end
    -- otherwise a router may forward it inside the allowed domain
    if node.role ~= "router" then
        node:log("MCAST_NOJOIN group=%s from=%s (host did not join)", M.int2ip(h.dst), M.int2ip(h.src))
        return "drop"
    end
    local egress = {}
    for pair in pairs(mc.domains) do
        local a, b = pair:match("^([^>]+)>(.+)$")
        if a == iface.name then egress[#egress + 1] = b end
    end
    if #egress == 0 then
        mc.denied = mc.denied + 1
        node:log("MCAST_DENY group=%s from=%s on=%s (no domain rule)", M.int2ip(h.dst), M.int2ip(h.src), iface.name)
        return "drop"
    end
    if not bucket_ok(mc, "mc:" .. h.dst .. ":" .. iface.name, mc.rate, now) then
        mc.rate_drops = mc.rate_drops + 1
        node:log("MCAST_RATE_DROP group=%s on=%s limit=%d/s", M.int2ip(h.dst), iface.name, mc.rate)
        return "drop"
    end
    mc.forwarded = mc.forwarded + 1
    node:log("MCAST_FORWARD group=%s from=%s on=%s -> %s", M.int2ip(h.dst), M.int2ip(h.src), iface.name, table.concat(egress, ","))
    return "forward", egress
end

return M
]==],
    qos = [==[
--[[- rpv/qos.lua ? multi-priority egress queues (control traffic wins).

Why: a CC router is single threaded and every transmit costs real time, so a bulk
transfer can sit in front of the one packet that matters -- a TCP-ish ACK from
conn.lua, an ICMP error, a routing announcement. With QoS enabled, `link_send`
queues frames instead of transmitting them, and a tick task drains the queues in
priority order with a per-tick budget.

Priorities (lower number = more urgent):
    0  control   : ICMP, ARP, conn pure ACKs (segment type 3, len 0), DV/announce
    1  interactive: UDP up to `qos_small` bytes (commands, telemetry, chat)
    2  bulk      : everything else (file transfers)

Config keys:
    qos=1                  enable
    qos_budget=16          frames drained per tick
    qos_budget_bytes=4096  byte budget per tick
    qos_max_queue=64       per-interface queue depth (drop lowest priority first)
    qos_small=96           "interactive" threshold in bytes
    qos_weights=4,2,1      drain weights for priorities 0,1,2 per tick round

API: rpv.qos_setup(node), rpv.qos_enqueue(node, iface, dstmac, etype, body),
     rpv.qos_classify(body, etype), rpv.qos_flush(node), rpv.qos_stats(node)

Logs: QOS_START, QOS_DROP, QOS_STATE tx= high= mid= low= dropped= queued= depth=.
]]
local M = ...
local u16, r16, byte, sub = M.u16, M.r16, M.byte, M.sub

-- 0 = control, 1 = interactive, 2 = bulk
function M.qos_classify(body, etype)
    if etype ~= M.ET_IP then return 0 end                    -- ARP and friends: control
    if #body < 20 then return 0 end
    local ihl = (byte(body, 1) % 16) * 4
    if ihl < 20 or #body < ihl then return 1 end
    local proto = byte(body, 10)
    if proto == M.IP_ICMP then return 0 end
    if proto == M.IP_UDP and #body >= ihl + 8 then
        local udp = sub(body, ihl + 1)
        -- conn.lua pure ACK: segment type 3 (DATA) with a zero length field
        if byte(udp, 9) == 3 and r16(udp, 20) == 0 then return 0 end
        if #udp - 8 <= (M.qos_small or 96) then return 1 end
        return 2
    end
    return 1
end

local function parse_weights(spec)
    local w = {}
    for n in tostring(spec or "4,2,1"):gmatch("%d+") do w[#w + 1] = tonumber(n) end
    if #w == 0 then w = { 4, 2, 1 } end
    return w
end

function M.qos_setup(node, opts)
    if node.cfg.qos ~= "1" then return nil end
    local q = {
        node = node,
        budget = tonumber(node.cfg.qos_budget) or 16,
        budget_bytes = tonumber(node.cfg.qos_budget_bytes) or 4096,
        max_queue = tonumber(node.cfg.qos_max_queue) or 64,
        small = tonumber(node.cfg.qos_small) or 96,
        weights = parse_weights(node.cfg.qos_weights),
        queues = {},              -- iface name -> { [prio] = {frames...} }
        tx = 0, high = 0, mid = 0, low = 0, dropped = 0, queued = 0, drained = 0,
    }
    M.qos_small = q.small
    node.qos = q
    node:log("QOS_START budget=%d frames/%d bytes per tick max_queue=%d small=%d weights=%s",
        q.budget, q.budget_bytes, q.max_queue, q.small, node.cfg.qos_weights or "4,2,1")

    node:add_task("qos", function()
        local nextReport = os.clock() + 5
        while true do
            M.qos_flush(node)
            os.sleep(0)
            local now = os.clock()
            if now >= nextReport then
                nextReport = now + 5
                local depth = 0
                for _, byPrio in pairs(q.queues) do
                    for _, list in pairs(byPrio) do depth = depth + #list end
                end
                node:log("QOS_STATE tx=%d high=%d mid=%d low=%d dropped=%d queued=%d depth=%d",
                    q.tx, q.high, q.mid, q.low, q.dropped, q.queued, depth)
            end
        end
    end)
    return q
end

local function depth_of(q, iface)
    local byPrio = q.queues[iface.name]
    if not byPrio then return 0 end
    local n = 0
    for _, list in pairs(byPrio) do n = n + #list end
    return n
end

function M.qos_enqueue(node, iface, dstmac, etype, body)
    local q = node.qos
    if not q then return false end
    local prio = M.qos_classify(body, etype)
    local byPrio = q.queues[iface.name]
    if not byPrio then byPrio = {}; q.queues[iface.name] = byPrio end
    local list = byPrio[prio]
    if not list then list = {}; byPrio[prio] = list end
    if depth_of(q, iface) >= q.max_queue then
        -- drop the least urgent frame we can find (never the urgent one we are adding
        -- unless the whole queue is priority 0)
        local victimPrio, victimList = nil, nil
        for p = 2, prio, -1 do
            local l = byPrio[p]
            if l and #l > 0 then victimPrio, victimList = p, l break end
        end
        if victimList then
            table.remove(victimList, 1)
            q.dropped = q.dropped + 1
            node:log("QOS_DROP prio=%d iface=%s depth=%d (queue full)", victimPrio, iface.name, depth_of(q, iface))
        else
            q.dropped = q.dropped + 1
            node:log("QOS_DROP prio=%d iface=%s depth=%d (only urgent traffic queued)", prio, iface.name, depth_of(q, iface))
            return true
        end
    end
    list[#list + 1] = { dstmac = dstmac, etype = etype, body = body, prio = prio }
    q.queued = q.queued + 1
    return true
end

-- drain the queues: all of priority 0 first (up to the budget), then weighted
-- rounds for 1 and 2 so bulk traffic cannot starve control traffic
function M.qos_flush(node)
    local q = node.qos
    if not q then return 0 end
    local sent, bytes = 0, 0
    q.bypass = true
    local function send_one(iface, item)
        return M.link_send(node, iface, item.dstmac, item.etype, item.body)
    end
    -- round robin across interfaces so one busy link cannot hold the others back
    for name, byPrio in pairs(q.queues) do
        local iface = node.by_iface and node.by_iface[name]
        if not iface then
            for _, i in ipairs(node.ifaces) do if i.name == name then iface = i end end
        end
        if iface then
            for prio = 0, 2 do
                local list = byPrio[prio]
                local weight = q.weights[prio + 1] or 1
                local allowance = (prio == 0) and q.budget or math.max(1, weight)
                local n = 0
                while list and #list > 0 and sent < q.budget and bytes < q.budget_bytes and n < allowance do
                    local item = table.remove(list, 1)
                    bytes = bytes + #item.body + 10
                    send_one(iface, item)
                    sent = sent + 1
                    n = n + 1
                    if prio == 0 then q.high = q.high + 1
                    elseif prio == 1 then q.mid = q.mid + 1
                    else q.low = q.low + 1 end
                end
                if sent >= q.budget or bytes >= q.budget_bytes then break end
            end
        end
    end
    q.bypass = false
    q.tx = q.tx + sent
    return sent
end

function M.qos_stats(node)
    local q = node.qos
    if not q then return nil end
    local depth = 0
    for _, byPrio in pairs(q.queues) do
        for _, list in pairs(byPrio) do depth = depth + #list end
    end
    return { tx = q.tx, high = q.high, mid = q.mid, low = q.low, dropped = q.dropped,
             queued = q.queued, depth = depth }
end

return M
]==],
    wansec = [==[
--[[- rpv/wansec.lua ? AEAD for the rednet WAN tunnel (control plane, P1b).

Same idea as the secure conn mode, applied to the WAN link: the tunnel is
authenticated and encrypted with a pre-shared key, so a computer that can hear the
rednet traffic (any modem on the WAN channel is enough) cannot read or forge it.

  * handshake: every node broadcasts `rpv-sec-hello` = mac + nonce + HMAC(k_ctrl).
    On a valid hello both sides derive per-peer session keys from the ordered
    (mac, nonce) pair, so both compute the same keys without another round trip.
  * data frames: `"S" | counter(4) | ChaCha20(frame) | tag(16)`, tag over
    `counter|ciphertext`. Retransmissions reuse the counter and produce the same
    ciphertext (same keystream), which is exactly what we want.
  * replay protection: per-peer monotonic counter + 64 frame sliding window.
  * control tables (rpv-advert / rpv-who-has / rpv-is-at) are signed over a
    canonical field list with k_ctrl.
  * fail-closed: with `wan_secure=1` a plaintext string frame, an unsigned table or
    a hello without a valid tag is dropped and counted; a peer we have no keys for
    cannot get anything through.

Config: wan_secure=1, wan_psk=<hex|passphrase>, wan_psk_iter=256,
        wan_sec_mac_len=16, wan_replay_window=64, wan_hello_interval=4

Logs: WANSEC_START, WANSEC_HELLO, WANSEC_KEYS, WANSEC_TX, WANSEC_RX, WANSEC_AUTH_FAIL,
      WANSEC_REPLAY, WANSEC_NO_KEYS, WANSEC_PLAINTEXT, WANSEC_STATE.
]]
local M = ...
local u8, u16, u32, r32, byte, sub = M.u8, M.u16, M.u32, M.r32, M.byte, M.sub

local HELLO = "rpv-sec-hello"

local function sec_is_hex(s)
    return #s >= 32 and #s % 2 == 0 and not s:find("[^0-9a-fA-F]")
end

function M.wansec_psk(node)
    local spec = node.cfg.wan_psk
    if not spec or spec == "" then return nil end
    local raw
    if sec_is_hex(spec) then
        raw = M.unhex(spec)
    else
        local iters = tonumber(node.cfg.wan_psk_iter) or 256
        raw = (iters > 0) and M.pbkdf2_sha256(spec, "rpv-wan", iters, 32, 32) or spec
    end
    return M.hkdf_sha256(raw, "", "rpv-wan-psk-v1", 32)
end

local function canon(msg)
    local keys = { "sType", "ver", "seq", "hops", "gw", "ip", "default", "mac", "nonce", "nets" }
    local parts = {}
    for _, k in ipairs(keys) do
        local v = msg[k]
        if type(v) == "table" then
            local t = {}
            for _, x in ipairs(v) do t[#t + 1] = tostring(x) end
            v = "[" .. table.concat(t, ",") .. "]"
        end
        parts[#parts + 1] = k .. "=" .. tostring(v)
    end
    return table.concat(parts, "|")
end

function M.wansec_setup(node, w)
    if node.cfg.wan_secure ~= "1" then return nil end
    local psk = M.wansec_psk(node)
    local sec = {
        node = node, w = w, mac = tonumber(node.cfg.wan_sec_mac_len) or 16,
        window = tonumber(node.cfg.wan_replay_window) or 64,
        peers = {}, tx = 0, rx = 0, auth_fail = 0, replay = 0, plaintext = 0, no_keys = 0,
        hellos = 0, enabled = psk ~= nil,
    }
    node.wansec = sec
    if not psk then
        node:log("WANSEC_FAIL_CLOSED no wan_psk (WAN tunnel will accept nothing)")
        return sec
    end
    sec.psk = psk
    sec.k_ctrl = M.hkdf_sha256(psk, "", "rpv-wan-ctrl-v1", 32)
    sec.nonce = M.random_bytes(8)
    sec.hello_tx = "HELLO|" .. tostring(node.mac) .. "|" .. sec.nonce
    node:log("WANSEC_START mac=%d hello_interval=%ss window=%d tag=%dB fail_closed=yes",
        node.mac, tostring(node.cfg.wan_hello_interval or 4), sec.window, sec.mac)
    return sec
end

function M.wansec_hello(node, w)
    local sec = node.wansec
    if not sec or not sec.enabled then return false end
    local tag = M.hmac_sha256(sec.k_ctrl, sec.hello_tx):sub(1, sec.mac)
    rednet.broadcast({ sType = HELLO, ver = 1, mac = node.mac, nonce = sec.nonce, tag = tag }, "rpv")
    sec.hellos = sec.hellos + 1
    node:log("WANSEC_HELLO sent nonce=%s tag=%s", M.hex(sec.nonce), M.hex(tag))
    return true
end

function M.wansec_hello_loop(node, w)
    M.wansec_hello(node, w)
    local st = M.wansec_stats(node)
    if st then
        node:log("WANSEC_STATE peers=%d tx=%d rx=%d auth_fail=%d replay=%d plaintext=%d no_keys=%d hellos=%d",
            st.peers, st.tx, st.rx, st.auth_fail, st.replay, st.plaintext, st.no_keys, st.hellos)
    end
    node:after(tonumber(node.cfg.wan_hello_interval) or 4, function() M.wansec_hello_loop(node, w) end)
end

-- derive per-peer keys; both sides use the ordered (mac, nonce) pair
local function derive_pair(sec, peer_mac, peer_nonce, my_nonce)
    local lo_mac, lo_nonce, hi_mac, hi_nonce
    if sec.node.mac < peer_mac then
        lo_mac, lo_nonce, hi_mac, hi_nonce = sec.node.mac, my_nonce, peer_mac, peer_nonce
    else
        lo_mac, lo_nonce, hi_mac, hi_nonce = peer_mac, peer_nonce, sec.node.mac, my_nonce
    end
    local salt = u32(lo_mac) .. lo_nonce .. u32(hi_mac) .. hi_nonce
    local k12 = M.hkdf_sha256(sec.psk, salt, "rpv-wan-lo2hi", 32)
    local m12 = M.hkdf_sha256(sec.psk, salt, "rpv-wan-lo2hi-mac", 32)
    local n12 = M.hkdf_sha256(sec.psk, salt, "rpv-wan-lo2hi-nonce", 12)
    local k21 = M.hkdf_sha256(sec.psk, salt, "rpv-wan-hi2lo", 32)
    local m21 = M.hkdf_sha256(sec.psk, salt, "rpv-wan-hi2lo-mac", 32)
    local n21 = M.hkdf_sha256(sec.psk, salt, "rpv-wan-hi2lo-nonce", 12)
    local p = { mac = peer_mac, tx = 0, rx_top = 0, seen = {}, nonce = peer_nonce, since = os.clock() }
    if sec.node.mac < peer_mac then
        p.k_tx, p.m_tx, p.nonce_tx = k12, m12, n12
        p.k_rx, p.m_rx, p.nonce_rx = k21, m21, n21
    else
        p.k_tx, p.m_tx, p.nonce_tx = k21, m21, n21
        p.k_rx, p.m_rx, p.nonce_rx = k12, m12, n12
    end
    return p
end

function M.wansec_hello_input(node, w, sender, msg)
    local sec = node.wansec
    if not sec then return false end
    if not sec.enabled then
        sec.auth_fail = sec.auth_fail + 1
        node:log("WANSEC_PLAINTEXT hello from=%s but we have no usable PSK", tostring(sender))
        return true                       -- consumed (fail closed)
    end
    local pmac = tonumber(msg.mac) or sender
    local pnonce = tostring(msg.nonce or "")
    local expect = M.hmac_sha256(sec.k_ctrl, "HELLO|" .. tostring(pmac) .. "|" .. pnonce):sub(1, sec.mac)
    if not M.equals(expect, tostring(msg.tag or "")) then
        sec.auth_fail = sec.auth_fail + 1
        node:log("WANSEC_AUTH_FAIL hello from=%s (bad tag)", tostring(sender))
        return true
    end
    if #pnonce ~= 8 then
        sec.auth_fail = sec.auth_fail + 1
        return true
    end
    local had = sec.peers[pmac]
    if had and had.nonce == pnonce then
        -- same session: keep the counters and the replay window. Re-deriving on every
        -- hello would reset them, letting a captured frame be replayed successfully.
        had.since = os.clock()
        return true
    end
    sec.peers[pmac] = derive_pair(sec, pmac, pnonce, sec.nonce)
    sec.peers[pmac].id = tonumber(sender) or pmac
    if not had then
        node:log("WANSEC_KEYS peer=%d rednet_id=%s fp=%s", pmac, tostring(sender),
            M.hex(M.sha256(sec.peers[pmac].k_tx)):sub(1, 8))
    else
        node:log("WANSEC_REKEY peer=%d (peer restarted with a new nonce)", pmac)
    end
    -- answer so the peer can derive the same keys even if it booted after us
    M.wansec_hello(node, w)
    return true
end

-- control tables: sign a canonical view of the message
function M.wansec_sign_table(node, msg)
    local sec = node.wansec
    if not sec or not sec.enabled then return msg end
    msg.mac = node.mac
    msg.tag = M.hmac_sha256(sec.k_ctrl, canon(msg)):sub(1, sec.mac)
    return msg
end

function M.wansec_verify_table(node, w, sender, msg)
    local sec = node.wansec
    if not sec then return true end
    if not sec.enabled then
        sec.auth_fail = sec.auth_fail + 1
        node:log("WANSEC_PLAINTEXT %s from=%s (no usable PSK)", tostring(msg.sType), tostring(sender))
        return false
    end
    local tag = tostring(msg.tag or "")
    local copy = {}
    for k, v in pairs(msg) do if k ~= "tag" then copy[k] = v end end
    local expect = M.hmac_sha256(sec.k_ctrl, canon(copy)):sub(1, sec.mac)
    if not M.equals(expect, tag) then
        sec.auth_fail = sec.auth_fail + 1
        node:log("WANSEC_AUTH_FAIL %s from=%s (bad table tag)", tostring(msg.sType), tostring(sender))
        return false
    end
    return true
end

-- data frames: "S" | counter(4) | ciphertext | tag(16)
function M.wansec_wrap(node, w, peer, frame)
    local sec = node.wansec
    if not sec or not sec.enabled then return nil end
    local p = sec.peers[peer]
    if not p then
        sec.no_keys = sec.no_keys + 1
        node:log("WANSEC_NO_KEYS peer=%d (handshake pending, frame dropped)", peer)
        return nil
    end
    p.tx = p.tx + 1
    local ct = M.chacha20_xor(p.k_tx, p.nonce_tx, p.tx, frame)
    local tag = M.hmac_sha256(p.m_tx, u32(p.tx) .. ct):sub(1, sec.mac)
    sec.tx = sec.tx + 1
    node:log("WANSEC_TX peer=%d counter=%d bytes=%d", peer, p.tx, #frame)
    return "S" .. u32(p.tx) .. ct .. tag
end

function M.wansec_unwrap(node, w, sender, env)
    local sec = node.wansec
    if not sec or not sec.enabled then return nil end
    local p = sec.peers[tonumber(sender)]
    if not p then
        sec.no_keys = sec.no_keys + 1
        node:log("WANSEC_NO_KEYS from=%s (no session keys)", tostring(sender))
        return nil
    end
    if #env < 5 + sec.mac then return nil end
    local counter = r32(env, 2)
    local ct = sub(env, 6, #env - sec.mac)
    local tag = sub(env, #env - sec.mac + 1)
    if not M.equals(M.hmac_sha256(p.m_rx, u32(counter) .. ct):sub(1, sec.mac), tag) then
        sec.auth_fail = sec.auth_fail + 1
        node:log("WANSEC_AUTH_FAIL data from=%s counter=%d (bad tag)", tostring(sender), counter)
        return nil
    end
    if counter <= p.rx_top - sec.window or p.seen[counter] then
        sec.replay = sec.replay + 1
        node:log("WANSEC_REPLAY from=%s counter=%d top=%d (dropped)", tostring(sender), counter, p.rx_top)
        return nil
    end
    p.seen[counter] = true
    if counter > p.rx_top then p.rx_top = counter end
    for c in pairs(p.seen) do if c <= p.rx_top - sec.window then p.seen[c] = nil end end
    sec.rx = sec.rx + 1
    node:log("WANSEC_RX from=%s counter=%d bytes=%d", tostring(sender), counter, #env - 5 - sec.mac)
    return M.chacha20_xor(p.k_rx, p.nonce_rx, counter, ct)
end

function M.wansec_stats(node)
    local sec = node.wansec
    if not sec then return nil end
    local n = 0
    for _ in pairs(sec.peers) do n = n + 1 end
    return { peers = n, tx = sec.tx, rx = sec.rx, auth_fail = sec.auth_fail, replay = sec.replay,
             plaintext = sec.plaintext, no_keys = sec.no_keys, hellos = sec.hellos }
end

return M
]==],
    compat = [==[
--[[- rpv/compat.lua ? runtime API self-check and version reporting.

CC:Tweaked and CraftOS-PC differ in small ways (emulator-only globals, rednet
availability, bit32 vs native bit operators), so every node reports what it found
at boot. A missing *required* API is loud; missing optional ones are listed.

    COMPAT ok=true os=CraftOS-PC 2.8.3 missing=- optional=periphemu,settings

Required: peripheral, fs, os.clock, os.getComputerID, string.format, table.concat,
          bit32 (or the native bit operators, which LuaJIT/5.2+ provide).
Optional: rednet (only needed for the WAN), periphemu (emulator-only modem creation),
          settings, colours/multishell (none used by the library).
]]
local M = ...

local REQUIRED = { "peripheral", "fs", "os", "string", "table" }
local OPTIONAL = { "rednet", "periphemu", "settings", "commands", "shell" }

function M.compat_check()
    local missing, optional = {}, {}
    for _, name in ipairs(REQUIRED) do
        if _G[name] == nil then missing[#missing + 1] = name end
    end
    if not (bit32 or _G.bit) then missing[#missing + 1] = "bit32" end
    if not (os and os.clock and os.getComputerID) then missing[#missing + 1] = "os.clock/getComputerID" end
    if not (fs and fs.open and fs.exists and fs.list) then missing[#missing + 1] = "fs.open/exists/list" end
    for _, name in ipairs(OPTIONAL) do
        if _G[name] == nil then optional[#optional + 1] = name end
    end
    return #missing == 0, missing, optional
end

function M.compat_setup(node)
    local ok, missing, optional = M.compat_check()
    local ver = "unknown"
    local got, v = pcall(function() return os.version and os.version() end)
    if got and type(v) == "string" then ver = v end
    node.compat = { ok = ok, missing = missing, optional = optional, version = ver }
    node:log("COMPAT ok=%s os=%s missing=%s optional=%s", tostring(ok), ver,
        #missing > 0 and table.concat(missing, ",") or "-",
        #optional > 0 and table.concat(optional, ",") or "-")
    if not ok then
        node:log("COMPAT_UNSUPPORTED the host is missing required APIs: %s", table.concat(missing, ","))
    end
    return ok
end

return M
]==],
    topo = [==[
--[[- rpv/topo.lua ? topology discovery and network-map output.

Every node periodically reports what it knows about itself and its neighbours; a
collector merges the reports into a map and can dump it as text. Nothing new is put
on the wire for discovery: a report is built from state the node already has (ARP
cache, DV routes, fabric peers, WAN peers, DHCP/DNS leases, NAT rules, group
membership), so enabling it costs one small datagram per interval.

Report (one UDP datagram, text so it is greppable in a capture):
    NODE id=<n> mac=<n> role=<role> ver=RPV1
    IFACE name=<n> cidr=<ip/prefix> ch=<n> mtu=<n> kind=<wired|wireless|wan|fabric>
    PEER ip=<ip> kind=<arp|dv|fabric|wan> [id=<n>]
    SVC dhcp=<0|1> leases=<n> dns=<0|1> nat=<n> mcast=<n> qos=<0|1> dv=<0|1>
    END

Map (collector):
    NETMAP_BEGIN nodes=<n> links=<m> at=<seconds>
    NODE id=<n> role=<role> addrs=<a,b,c> peers=<n>
    LINK <a><-><b> via=<iface> kind=<...>
    NETMAP_END

Config keys:
    topo=1                     report periodically on this node
    topo_server=<ip>           send reports to this collector (else limited broadcast)
    topo_interval=5            report period
    topo_collect=1             this node is a collector (binds topo_port)
    topo_port=6900
    topo_dump=1                write netmap.txt + NETMAP_* lines every topo_dump_every
    topo_dump_every=10
    topo_ttl=20                a node disappears from the map after this long

API: rpv.topo_setup(node), rpv.topo_report(node), rpv.topo_input(node, text, src),
     rpv.topo_dump(node), rpv.topo_text(node), rpv.topo_map(node), rpv.topo_stats(node)
]]
local M = ...
local u8, u16, u32, r32, byte, sub = M.u8, M.u16, M.u32, M.r32, M.byte, M.sub

local PORT = 6900

local function split(s)
    local out = {}
    for line in tostring(s):gmatch("[^\r\n]+") do out[#out + 1] = line end
    return out
end

-- build our own report from existing state
function M.topo_report_text(node)
    local lines = {}
    lines[#lines + 1] = string.format("NODE id=%d mac=%d role=%s ver=%s",
        node.id or 0, node.mac or 0, tostring(node.role), tostring(M.RPV_VERSION or "RPV1"))
    for _, i in ipairs(node.ifaces or {}) do
        local kind = i.is_wan and "wan" or (i.is_fabric and "fabric") or (i.wireless and "wireless" or "wired")
        lines[#lines + 1] = string.format("IFACE name=%s cidr=%s ch=%s mtu=%s kind=%s",
            tostring(i.name), tostring(i.cidr), tostring(i.channel), tostring(i.mtu), kind)
    end
    local seen = {}
    local function peer(ip, kind, id)
        if not ip or ip == 0 or seen[ip] then return end
        seen[ip] = true
        lines[#lines + 1] = string.format("PEER ip=%s kind=%s%s", M.int2ip(ip), kind,
            id and (" id=" .. tostring(id)) or "")
    end
    if node.arp and node.arp.cache then
        for ip in pairs(node.arp.cache) do peer(ip, "arp") end
    end
    if node.dv then
        for _, r in pairs(node.dv.routes) do
            if not r.own then peer(r.gw, "dv") end
        end
    end
    if node.fabric and node.fabric.peers then
        for member in pairs(node.fabric.peers) do
            lines[#lines + 1] = string.format("PEER id=%d kind=fabric", member)
        end
    end
    if node.wan and node.wan.peers then
        for ip, id in pairs(node.wan.peers) do peer(ip, "wan", id) end
    end
    local leases = 0
    if node.dhcp and node.dhcp.by_ip then for _ in pairs(node.dhcp.by_ip) do leases = leases + 1 end end
    local groups = 0
    if node.mcast and node.mcast.groups then for _ in pairs(node.mcast.groups) do groups = groups + 1 end end
    local rules = 0
    if node.nat and node.nat.rules then for _ in pairs(node.nat.rules) do rules = rules + 1 end end
    lines[#lines + 1] = string.format("SVC dhcp=%d leases=%d dns=%d nat=%d mcast=%d qos=%d dv=%d",
        node.dhcp and 1 or 0, leases, node.dns and 1 or 0, rules, groups,
        node.qos and 1 or 0, node.dv and 1 or 0)
    lines[#lines + 1] = "END"
    return table.concat(lines, "\n")
end

function M.topo_send(node)
    local text = M.topo_report_text(node)
    local server = node.cfg.topo_server and M.ip2int(node.cfg.topo_server)
    local port = tonumber(node.cfg.topo_port) or PORT
    if server then
        M.udp_send(node, server, port, port, text)
    else
        M.udp_send(node, M.IP_BCAST, port, port, text, 1)
    end
    if node.topo then
        node.topo.reports_sent = (node.topo.reports_sent or 0) + 1
        -- low-rate evidence that this node is reporting (every 4th report)
        if node.topo.reports_sent % 4 == 1 then
            node:log("TOPO_SENT from=%s n=%d ifaces=%d bytes=%d",
                M.int2ip(node.ifaces[1] and node.ifaces[1].ip or 0), node.topo.reports_sent, #node.ifaces, #text)
        end
    end
    return true
end

function M.topo_new(node, opts)
    return {
        node = node, port = tonumber(node.cfg.topo_port) or PORT,
        interval = tonumber(node.cfg.topo_interval) or 5,
        ttl = tonumber(node.cfg.topo_ttl) or 20,
        collect = node.cfg.topo_collect == "1",
        nodes = {},            -- id -> { role, addrs = {..}, peers = {..}, seen = t }
        links = {},            -- "a|b" -> { a, b, via, kind }
        by_addr = {},          -- ip -> node id
        reports_rx = 0, reports_sent = 0, dumps = 0,
    }
end

-- merge one received report
function M.topo_input(node, text, src)
    local topo = node.topo
    if not topo or not topo.collect then return false end
    local cur = nil
    for _, line in ipairs(split(text)) do
        local head = line:match("^(%u+)")
        if head == "NODE" then
            local id = tonumber(line:match("id=(%d+)"))
            if not id then return false end
            cur = topo.nodes[id] or { id = id, addrs = {}, peers = {} }
            cur.role = line:match("role=(%S+)") or cur.role
            cur.seen = os.clock()
            topo.nodes[id] = cur
        elseif head == "IFACE" and cur then
            local cidr = line:match("cidr=(%S+)")
            local name = line:match("name=(%S+)")
            if cidr then
                cur.addrs[cidr] = true
                local ip = cidr:match("^([%d%.]+)")
                if ip then topo.by_addr[M.ip2int(ip)] = cur.id end
            end

        elseif head == "PEER" and cur then
            local ip = line:match("ip=(%S+)")
            local key = line:match("kind=(%S+)")
            if ip then
                cur.peers[ip] = key or "?"
            elseif line:match("id=(%d+)") and key == "fabric" then
                cur.peers["#" .. line:match("id=(%d+)")] = "fabric"
            end
        end
    end
    if not cur then return false end
    topo.reports_rx = topo.reports_rx + 1
    node:log("TOPO_REPORT_RX from=%s id=%s reports_rx=%d nodes=%d",
        M.int2ip(src or 0), tostring(cur.id), topo.reports_rx, (function()
            local n = 0
            for _ in pairs(topo.nodes) do n = n + 1 end
            return n
        end)())
    M.topo_rebuild(node)
    return true
end

-- turn the peer lists into links (peer ip -> the node that owns that address)
function M.topo_rebuild(node)
    local topo = node.topo
    if not topo then return 0 end
    topo.links = {}
    local function link(a, b, via, kind)
        if not a or not b or a == b then return end
        local key = a < b and (a .. "|" .. b) or (b .. "|" .. a)
        local l = topo.links[key]
        if not l then
            topo.links[key] = { a = math.min(a, b), b = math.max(a, b), via = via, kind = kind }
        elseif l.kind ~= kind then
            l.kind = l.kind .. "+" .. kind
        end
    end
    for id, n in pairs(topo.nodes) do
        if n.peers then
            for key, kind in pairs(n.peers) do
                local target = nil
                if key:sub(1, 1) == "#" then
                    target = tonumber(key:sub(2))
                else
                    local ip = M.ip2int(key)
                    target = topo.by_addr[ip]
                end
                link(id, target, n.role, kind)
            end
        end
    end
    local count = 0
    for _ in pairs(topo.links) do count = count + 1 end
    return count
end

function M.topo_expire(node)
    local topo = node.topo
    if not topo then return 0 end
    local now, dropped = os.clock(), 0
    for id, n in pairs(topo.nodes) do
        if n.seen and now - n.seen > topo.ttl then
            topo.nodes[id] = nil
            dropped = dropped + 1
        end
    end
    if dropped > 0 then M.topo_rebuild(node) end
    return dropped
end

function M.topo_map(node)
    local topo = node.topo
    if not topo then return nil end
    return topo
end

-- text rendering: short lines, one node / one link per line (grep friendly)
function M.topo_text(node)
    local topo = node.topo
    if not topo then return "NETMAP_BEGIN nodes=0 links=0\nNETMAP_END" end
    local ids = {}
    for id in pairs(topo.nodes) do ids[#ids + 1] = id end
    table.sort(ids)
    local linkKeys = {}
    for k in pairs(topo.links) do linkKeys[#linkKeys + 1] = k end
    table.sort(linkKeys)
    local out = {}
    out[#out + 1] = string.format("NETMAP_BEGIN nodes=%d links=%d at=%.0f", #ids, #linkKeys, os.clock())
    for _, id in ipairs(ids) do
        local n = topo.nodes[id]
        local addrs = {}
        for a in pairs(n.addrs) do addrs[#addrs + 1] = a end
        table.sort(addrs)
        local peers = 0
        for _ in pairs(n.peers) do peers = peers + 1 end
        out[#out + 1] = string.format("NODE id=%d role=%s addrs=%s peers=%d", id, tostring(n.role),
            #addrs > 0 and table.concat(addrs, ",") or "-", peers)
    end
    for _, k in ipairs(linkKeys) do
        local l = topo.links[k]
        out[#out + 1] = string.format("LINK %d<->%d kind=%s", l.a, l.b, tostring(l.kind))
    end
    out[#out + 1] = "NETMAP_END"
    return table.concat(out, "\n")
end

function M.topo_dump(node, path)
    local text = M.topo_text(node)
    path = path or "netmap.txt"
    local f = fs.open(path, "w")
    if f then
        f.writeLine(text)
        f.close()
    end
    if node.topo then node.topo.dumps = node.topo.dumps + 1 end
    for _, line in ipairs(split(text)) do node:log("%s", line) end
    return text
end

function M.topo_stats(node)
    local topo = node.topo
    if not topo then return nil end
    local n, l = 0, 0
    for _ in pairs(topo.nodes) do n = n + 1 end
    for _ in pairs(topo.links) do l = l + 1 end
    return { nodes = n, links = l, reports_rx = topo.reports_rx, reports_sent = topo.reports_sent, dumps = topo.dumps }
end

function M.topo_setup(node, opts)
    if node.cfg.topo ~= "1" and node.cfg.topo_collect ~= "1" then return nil end
    local topo = M.topo_new(node, opts)
    node.topo = topo
    node:log("TOPO_START collect=%s port=%d interval=%ds ttl=%ds", tostring(topo.collect), topo.port, topo.interval, topo.ttl)
    if topo.collect then
        node:bind(topo.port, function(data, src, sport)
            M.topo_input(node, tostring(data), src)
        end)
    end
    node:add_task("topo", function()
        local nextDump = os.clock() + (tonumber(node.cfg.topo_dump_every) or 10)
        while true do
            os.sleep(topo.interval)
            if node.cfg.topo == "1" then M.topo_send(node) end
            M.topo_expire(node)
            if topo.collect and node.cfg.topo_dump == "1" and os.clock() >= nextDump then
                nextDump = os.clock() + (tonumber(node.cfg.topo_dump_every) or 10)
                M.topo_dump(node)
            end
            if topo.collect then
                local n, l = 0, 0
                for _ in pairs(topo.nodes) do n = n + 1 end
                for _ in pairs(topo.links) do l = l + 1 end
                node:log("TOPO_STATE nodes=%d links=%d reports_rx=%d reports_sent=%d dumps=%d",
                    n, l, topo.reports_rx, topo.reports_sent, topo.dumps)
            end
        end
    end)
    return topo
end

return M
